export default [{"id":1304,"question":"ورد في الحديث في أوصاف الذين يدخلون الجنةَ بغير حسابٍ، قال: هم الذين لا يرقون –أو: لا يسترقون- ولا يتطيَّرون، وعلى ربهم يتوكَّلون، فهل من الممكن أن تشرح لنا هذه الأوصاف؟","title":"معنى \"لا يَسْتَرْقُون ولا يَكْتَوُون\" في الحديث","answer":"الجواب:\nنعم، نعم، لا يَسْتَرْقُون، ولا يَكْتَوُون يعني: أنهم يتركون الحاجة إلى الناس في طلب الاسترقاء، إذا استغنوا عن ذلك، إذا لم يكن لهم حاجة، وهكذا الكي.  أما إذا احتاجوا فلا بأس، النبي ﷺ كوى بعضَ أصحابه وقال: الشِّفاء في ثلاثة: كَيَّة نار، وشَرْطَة مِحْجَم، وشربة عسل، وما أحب أن أكتوي، وفي لفظٍ: وأنا أنهى أمتي عن الكيّ، فالمعنى: أنَّ هذا أفضل، ترك الكي والاسترقاء أفضل، إلا عند الحاجة.\nوأمر عائشة وأسماء بنت عميس أن تسترقي للأولاد الذين أصابتهم العين، فالاسترقاء عند الحاجة لا بأس به، لكن إذا استُغني عن هذا بدواءٍ آخر وعلاجٍ آخر فهو أوْلى من سؤال الناس الاسترقاء -سؤال الناس أن يرقوه-. والكي معروفٌ، الكي بالنار معروفٌ.\nأما رواية: لا يَرْقُون ذكر المحققون أنَّها وهمٌ وغلطٌ، وإنما المحفوظ: لا يسترقون، وورد في رواية مسلم: لا يرقون، ولكنَّها رواية غلط من بعض الرواة، كما قال شيخُ الإسلام ابن تيمية رحمه الله وجماعة: أنها غلط؛ لأنَّ الرسول رقى ورُقِيَ عليه الصلاة والسلام، وحثَّ على الرقية قال: مَنِ اسْتَطَاعَ مِنكُم أَنْ يَنْفَعَ أَخَاهُ فَلْيَنْفَعْهُ، فالرُّقية مطلوبةٌ ومشروعةٌ ومأمورٌ بها.","link":"https://binbaz.org.sa/fatwas/21365/معنى-لا-يسترقون-ولا-يكتوون-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1108ما معنى قول النبي صلى الله عليه وسلم لايسترقون ولايكتوون؟ابن باز فتاوى.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":1356,"question":"إذا أصيب إنسان بعين ولا يعرف مَن أصابه كيف العلاج؟","title":"ماذا يفعل مَنْ ظن إصابته بعين ونحوها؟","answer":"الجواب:\nويش يدريه أنه أُصيب بالعين؟\nس: مثلاً أحيانًا يكون فيه ضيق الصدر؟\nج: ما هو كلها على أنها عين، قد تكون أمراضًا داخلية غير العين، لكن إذا ظن بإنسان يطلب منه أن يغسل له وجهه ويديه أو يتوضأ له وجهه وكفيه وأطراف قدميه، كما جاء في الحديث، ثم يتروَّش بذلك، إذا تيسر له ذلك.\nس: بعض الناس مثلاً يقول: هذا نَفس فيه يعني أصابته نفس؟\nج: عند الناس الظنون كثيرة اللي ما عليها سلطان، هذا يظن \"نفس\"، وهذا يظن \"سحر\"، وهذا يظن \"جن\"، الناس يتخبطون في المسائل هذه.\nس: يعني يكتفي بالرقية؟\nج: الرقية كافية لكل شيء، إلا مِن عَيْن أو حمَّة.","link":"https://binbaz.org.sa/fatwas/21449/ماذا-يفعل-من-ظن-اصابته-بعين-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الإصابة بالعين والرقية منها.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":1907,"question":"ما رأيك فيما يفعله بعضُ القُرَّاء إذا نطق جنيٌّ على لسان شخصٍ، فيستدرجه في بعض الأسئلة ويُسْمِع الحاضرين؟ ما رأيكم في هذه؟","title":"حكم تحاور قارئ الرقية مع الجِن أمام الناس","answer":"الجواب:\nالمقصود أنه يُحَذِّره ويقول له: إنك ظالم، وأن هذا ما يجوز لك، والواجب عليك الخروج، ويقرأ الآيات التي تُضايقه وتجعله يحرص على الخروج؛ لأنَّه ضدّ القرآن، فهم يغضبون من القرآن، وتُؤذيهم قراءة القرآن، وإذا سأله عن الأسباب فلا بأس: ما الذي أدخلك؟ ما الذي جاء بك؟ لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/22019/حكم-تحاور-قارى-الرقية-مع-الجن-امام-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يفعله بعضُ القُرَّاء إذا نطق جنيٌّ على لسان شخصٍ يُسْمِع الحاضرين.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":1916,"question":"أحد الشباب عندنا لديه اختبارات في الجامعة، فذهب إلى أحد الأئمة كي يكتب له ورقةً فيها بركة؟","title":"حكم التمائم والحروز بآيات القرآن وغيرها","answer":"الجواب:\nحِرْزٌ يعني؟\nس: نعم.\nج: تميمة؟\nس: نعم.\nج: لا، التمائم لا تجوز.\nس: هل هي شركٌ أكبر أم شركٌ أصغر؟\nج: هي شركٌ أصغر، التمائم وما يُسمَّى الحروز وما يُسمَّى الجوامع هذه ما تجوز، النبي ﷺ قال: مَن تعلَّق تميمةً فلا أتمّ الله له، ومَن تعلَّق ودعةً فلا ودعَ الله له، ومَن تعلَّق تميمةً فقد أشرك.\nس: والذي يُؤمن بهذا الحِرْز؟\nج: يُعَلَّم ويُنْصَح، يُعَلَّم بالأحاديث، لكن بعض أهل العلم رخَّص فيها إذا كان فيها آيات من القرآن، والصواب أنها لا تجوز مطلقًا، حتى من القرآن لا تُعلَّق.\nس: حتى آيات القرآن؟\nج: لا تُعلَّق، إنما يُنفث بها وتُقرأ، فيقرأ عليه وينفث عليه ولا بأس، أما أن يجعلها في شيءٍ ويُعلِّقها في رقبته أو في يده فلا.","link":"https://binbaz.org.sa/fatwas/22029/حكم-التماىم-والحروز-بايات-القران-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التميمة شرك ولو كانت من رجل صالح.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":2275,"question":"التَّميمة إذا كانت من القرآن ما الصواب فيها؟","title":"حكم التميمة إذا كانت من القرآن","answer":"الجواب:\nالمنع، يُسمَّى: الحروز، والتَّمائم من القرآن وغير القرآن: الصواب منعها.\nس: لكن إذا كانت من القرآن هل تصل إلى حدِّ الشرك الأكبر؟\nج: الشرك الأصغر؛ لأنها وسيلةٌ، ولعموم الأدلة.\nس: والأكبر إذا اعتقد النفعَ والضرَّ أو كيف؟\nج: الأكبر إذا اعتقد أنها هي التي تنفع بنفسها، أو تدفع الضرَّ بنفسها.","link":"https://binbaz.org.sa/fatwas/22398/حكم-التميمة-اذا-كانت-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التَّميمة إذا كانت من القرآن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4099,"question":"إذا رقى نفسه؟","title":"ما حكم رقية المرء نفسه؟","answer":"الجواب: هذا من المشروع، من السُّنة، من الطبِّ المشروع، كان النبي يرقي نفسَه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24339/ما-حكم-رقية-المرء-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من الطب المشروع أن يرقي الإنسان نفسه.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4101,"question":"رقية جبريل له، ما كانت بطلب منه عليه الصلاة والسلام؟","title":"كيف كانت رقية جبريل للنبي عليه الصلاة والسلام؟","answer":"الجواب: ما بلغني.\nس: رقية جبريل؟\nج: من تبرع جبرائيل، ما بلغنا أنه استرقى ﷺ، وهكذا رقيته لنفسه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24341/كيف-كانت-رقية-جبريل-للنبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في رقية جبريل للنبي عليه الصلاة والسلام.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":4130,"question":"هل الأفضل للمريض عدم طلب الرقية؟","title":"هل الأفضل للمريض ترك طلب الرقية؟","answer":"الجواب: الأفضل نعم، إلا إذا دعت الحاجة إلى ذلك، مثلًا ما تيسر له أسباب أخرى، ولهذا أمر النبي أن يسترقى من العين، ومثل الكي تركه أولى، مكروه، وإذا دعت الحاجة إليه زالت الكراهة.","link":"https://binbaz.org.sa/fatwas/24376/هل-الافضل-للمريض-ترك-طلب-الرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل للمريض عدم طلب الرقية.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4247,"question":"إذا كانت التميمة شيئًا من القرآن هل يكون من الشرك؟","title":"ها تجوز التميمة من القرآن؟","answer":"الجواب: ولو، الصحيح أنها لا  تُعَلَّق حتى من القرآن.\nس: يكون من الشرك؟\nج: الصحيح أنه من الشرك الأصغر، التعليق بعض الفقهاء بعض السلف أجازها إن كانت من القرآن، والأحاديث عامة: تعم القرآن وغيره، تعم التمائم كلها.","link":"https://binbaz.org.sa/fatwas/24516/ها-تجوز-التميمة-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التميمة من القرآن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4248,"question":"هناك دليل يجوِّز للإنسان أن يكتب شيئًا من القرآن ويمسحه ويشربه؟","title":"حكم كتابة شيء من القرآن ومسحه وشربه","answer":"الجواب: هذا فعله السلف، يسمونه الرقية في صحن أو ورقة من الزعفران ويغسل، فعله بعض السلف، ذكره ابن القيم عن كثير من السلف الصالح أنه ينفع بإذن الله، يكتب آيات بالزعفران أو الأدعية ثم يغسلها ويشربها.\nس: يعني من يفعل هذا لا يُنكر عليه؟\nج: لا حرج؛ لأنه ما هو تعليق، شُرب.","link":"https://binbaz.org.sa/fatwas/24518/حكم-كتابة-شيء-من-القران-ومسحه-وشربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على كتابة شيء من القرآن ومسحه وشربه.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4250,"question":"من يتعلّقون بهذه الأشياء تعليق التمائم وغيرها إذا إنسان نصحهم وذكرهم يقولون: هذه الآيات نزلت في المشركين في عهد النبي ﷺ أما نحن مسلمون؟","title":"هل النهي عن التمائم خاص بالمشركين؟","answer":"الجواب: الرسول ﷺ نهى عن هذا، الرسول قال: من تعلق تميمة فلا أتم الله له، نهى الله عن هذا وقال: لا تزيدك إلا وهنا قال لعمران وقال: من تعلق تميمة فقد أشرك، يبين له الأحاديث، أن هذه التعليقات تصرف القلوب عن الله، تصرف القلوب إلى المخلوقات.\nس: الآيات عامة تشملهم وغيرهم؟\nج: نعم، حسب ما جاء في النصوص. أما الأدوية النافعة والأسباب الشرعية فلا بأس بها، مثل ما يأكل الإنسان ويشرب، ومثل ما يلبس في الشتاء الشيء الدافي، وفي الصيف الشيء الخفيف، ومثل ما يتروّح بالمروحة.","link":"https://binbaz.org.sa/fatwas/24520/هل-النهي-عن-التماىم-خاص-بالمشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن التمائم عام في كل وقت.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4256,"question":"تعليق السبحة على السيارة هل هو من جنس التمائم؟","title":"هل تعليق السبحة في السيارة يُعَدُّ من التمائم؟","answer":"الجواب: إن كان قصده لهذا ما يجوز، إن كان قصده تعليق تمائم ما يجوز، لدفع البلاء ما يجوز. وإن كان قصده علقها زينة فلا بأس، مثل ما يعلق في الجدران الآيات للذكرى.","link":"https://binbaz.org.sa/fatwas/24526/هل-تعليق-السبحة-في-السيارة-يعد-من-التماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق السبحة على السيارة.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4257,"question":"ما يسمى \"الحصن الحصين\" الذي يباع في الحج فيه سورة يس، وآية الكرسي، ويحطونها في صندوق أحمر ويبيعونها؟","title":"حكم كتاب \"الحصن\" الذي يباع في الحج","answer":"الجواب: ما يصلح هذا.\nس: وحكم من يبيعها؟\nج: يعلم أنه لا يجوز؛ لأن هذا دعوة إلى التمائم.\nس: وإذا كانوا وافدين ولا معه؟\nج: يعلم يعلم ينصح.\nس: ما تسحب منه؟\nج: بالقوة لا، من باب النصيحة إلا إذا كان الساحب من أهل الأمر مثل الهيئة وأشباهها لأن القوة من غيرهم يسبب مشاكل.","link":"https://binbaz.org.sa/fatwas/24527/حكم-كتاب-الحصن-الذي-يباع-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتاب الحصن الحصين.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4333,"question":"يقول بعض القراء: يضع يده على رأس المرأة التي يقرأ عليها، فما حكم ذلك؟","title":"حكم لمس الرجل رأس المرأة في الرقية","answer":"الجواب: إذا كان من وراء حائل ما يضر، إذا كان من وراء حائل لتثبيت القراءة، أما المباشرة لا، إن كان من وراء حائل أو وراء خمار أو وراء العباءة التي تثبت حتى يقرأ عليها لا تحرك رأسها.","link":"https://binbaz.org.sa/fatwas/24608/حكم-لمس-الرجل-راس-المراة-في-الرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع يد القارئ على رأس المرأة التي يقرأ عليها.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4340,"question":"كتاب الشيخ ابن عثيمين المفيد في شرح كتاب التوحيد يقول: وقد ذكر بعض أهل العلم أن من العلاج أن يطلقها زوجها إن كان محبوسا الزوج عن زوجته، يقول من العلاج: أن يطلقها ثم يراجعها. طبعا الشيخ هنا يقول: لا أدري عن صحته؟","title":"ما علاج من كان محبوسًا عن زوجته؟","answer":"الجواب: والله ما بلغني، ما أعرف له أصلًا، هذا مشهور عندهم، ولكن ما أعرف له أصلًا.  العلاج يعالجها بالدعوات الشرعية والرقية الشرعية ويبشر بالخير إن شاء الله.\nس: مشهور عند من؟\nج: عند العامة.\nس: يطلقها ويراجعها؟\nج: لا، ما له أصل، هذا من كلام العامة الذي ما له أساس، العامة عندهم خرافات كثيرة.","link":"https://binbaz.org.sa/fatwas/24615/ما-علاج-من-كان-محبوسا-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علاج من كان محبوسًا عن زوجته.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5011,"question":"سورة الزلزلة هل تُؤثر على حمل مريضةٍ بالمس سحرًا أو حسدًا؟ تقول إن أحدُ القُرَّاء قال: إنها إذا قُرِئَتْ عليها فإنَّها تُؤثِّر على حملها؟","title":"هل صح أن لسورة الزلزلة أثرًا على الحمل؟","answer":"الجواب: لا، ما له أصل هذا، هذه خرافة.","link":"https://binbaz.org.sa/fatwas/28813/هل-صح-ان-لسورة-الزلزلة-اثرا-على-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صح أن لسورة الزلزلة أثرًا على الحمل؟.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5019,"question":"مَن يُشغل الشريطَ في البيت ليطرد الجنَّ، هل يُشرع؟","title":"حكم تشغيل شريط قرآن بالبيت لطرد الجن","answer":"الجواب: ما أعلم فيه شيئًا، ما فيه بأس.","link":"https://binbaz.org.sa/fatwas/28831/حكم-تشغيل-شريط-قران-بالبيت-لطرد-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تشغيل شريط قرآن بالبيت لطرد الجن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5970,"question":"أخ يسأل عن الآيات التي تقرأ على المسحور، والممنوع عن زوجته ما هي؟","title":"الآيات التي تقرأ على المسحور والمصاب بالعين","answer":"الجواب: ذكر كثير من أهل العلم: أن من أسباب العافية للمسحور، والذي حبس عن زوجته: أن يقرأ آيات ثلاث التي في سورة يونس، وسورة الأعراف، وطه المتعلقة بالسحر، يقرأها، وتقرئ على المسحور، وعلى المحبوس عن زوجته، مع آية الكرسي، ومع قل يا أيها الكافرون، وقل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، هذه يقرأها على المريض، أو في ماء، ويشربه المريض، ويشفى بإذن الله. وإن جعل معها سبع ورقات سدر، دقها، وجعلها في الماء، وقرأ في ذلك أيضًا ينفع هذا، وهذا، يقرأ على المريض، أو في ماء يقرأ فيه آيات السحر من سورة الأعراف، ومن سورة يونس، ومن سورة طه، ويقرأ معها آية الكرسي، وقل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، ثم يشرب منها المسحور، والمحبوس عن زوجته، ويتروش بالباقي، هذا ينفع، وجربناه كثيرًا، وكذلك إذا قرئ على المريض نفسه، هذه الآيات ينفعه كثيرًا. السؤال: سؤال عن العلاج من إصابة العين؟ الشيخ: كذلك العين الرقية تنفع فيها، يرقية من الآيات التي تناسب في القرآن، ويدعو له، وينفث عليه في ذلك، هذا ينفعه، النبي -عليه الصلاة والسلام- قال: لا رقية إلا من عين، أو حمة وإذا عرف العاين؛ يأمره أن يغسل وجهه، ويتمضمض من أطرافه في إناء، ثم يغتسل بهذا الماء، وتزول العين -بإذن الله- إذا كان معروفًا. السؤال: إذا كان يؤاذيه، ياشيخ، ويكون شحناء، وعداوة؟ الشيخ: إذا عرف، يتوسل إليه بالطريقة الطيبة، يقال: هذا ما يضرك، وهذا أمر الله، والعين حق، يجب عليك أن توافق، وأن تغتسل له أطرافك، وتمضمض، وتغسل وجهك، ويديك، وتعطيه من هذا؛ ينفع -بإذن الله- أيش يضرك، ويجوز للحاكم أن يلزمه بذلك، إذا عرف. السؤال: ما حكم من يقرأ على المجنون، ويدعي بأنه يكلمون الجن، ويطلعهم من الشخص؟ الشيخ: هذا واقع، إذا قرأ عليهم؛ قد يخرجوا -بإذن الله- إذا كان جيدًا، وصاحب إيمان، قد يخرج الجن بقراءته، وقد يضربهم أيضًا، إذا كان معروفًا وليس معروفًا بالسحر، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/1366/الايات-التي-تقرا-على-المسحور-والمصاب-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_324.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5980,"question":"رجل يقرأ على المرضى بالقرآن، والأدعية النبوية، وقبل القراءة يحدد المال الذي سيأخذه من المريض، فما هو رأي سامحتكم في هذا؟","title":"حكم أخذ المال مقابل الرقى الشرعية على المرضى","answer":"الجواب: لا بأس بذلك إذا كان يقرأ ما تيسر من القرآن، ويدعو لهم بالدعوات، وينفث على المريض، لا بأس أن يحدد الأجر الذي له.  كما وقع لبعض الصحابة مع لديغ لدغ، وكانوا نزلوا بهم، ولم يضيفوهم، فجاءوا إليهم يطلبون من يرقي ليرقي هذا المريض، فقالوا: إلا أن تضربوا لنا سهمًا، فضربوا لهم شيئًا قطيعًا من الغنم، فرقوه حتى عافاه الله، وسلموا لهم نفس الأجرة، وبلغوا النبي ﷺ فأقرهم على ذلك.","link":"https://binbaz.org.sa/fatwas/1362/حكم-اخذ-المال-مقابل-الرقى-الشرعية-على-المرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_320.mp3","categories":["الإجارة","الطب والتداوي","الرقى والتمائم"]},{"id":6728,"question":"وتخصصي هو النساء، والولادة حيث إن هذا التخصص شاق على النساء، وغالبًا ما يكون مستواهم ضعيف فيه، فنحتاج كثيرًا إلى الرجال في هذا التخصص، فهل يجوز لي العمل في هذا التخصص، مع العلم أنني شخصيًا غيور جدًا، ولا أرضى لأهلي أن يكشفوا على رجال، وإن كان في تخصص باطنية، أو جلدية، فأفتونا جزاكم الله خيرًا؟","title":"حكم تخصص الرجال في طب النساء والولادة","answer":"الجواب: على كل حال هذا التخصص خطير، ويخشى منه على الرجل شر كثير، ولكن إذا دعت إليه الضرورة؛ لا بأس، لكن إذا تولاه النساء هو الذي ينبغي، إذا تخصص به النساء، واجتهد في تعليم النساء لهذا الأمر؛ يكون أولى، وأنفع للنساء، وأبعد عن الشر، ولكن قد تدعو الحاجة إلى تخصص الرجال؛ فلا يضر.","link":"https://binbaz.org.sa/fatwas/2604/حكم-تخصص-الرجال-في-طب-النساء-والولادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1100.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":6870,"question":"ما مدى صحة حديث: أعطوا الأجير أجره قبل أن يجف عرقه؟","title":"درجة حديث: «أعطوا الأجير أجره»","answer":"الجواب: هذا ضعيف، حديث ضعيف، لكن يغني عنه حديث آخر صحيح يقول النبي ﷺ: يقول الله: ثلاثة أنا خصمهم يوم القيامة، ومن كنت خصمه خصمته، رجل أعطى بي ثم غدر، ورجل باع حرًا فأكل ثمنه، ورجل استأجر أجيرًا فاستوفى منه، ولم يعطه أجره. الواجب يعطى أجره، ولكن كونه يبادر قبل أن يجف عرقه، هذا الحديث ضعيف. والظاهر البدار بإعطائه إياه، ولو بعد ما جف عرقه.","link":"https://binbaz.org.sa/fatwas/2758/درجة-حديث-اعطوا-الاجير-اجره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1250.mp3","categories":["الإجارة","الرقى والتمائم"]},{"id":7179,"question":"بعض أئمة المساجد والشيوخ يقرؤون على الناس بآيات من القرآن والدعاء، فيعلموهم ماذا أصابهم، فبعضهم يقول له: أصابك سحر، وبعضهم يقول: أصابتك عين، إلى غير ذلك من الكلام الذي يقولون، فما حكمكم في هؤلاء، وحكم الذهاب إليهم، وحكم التصديق بهم؟ وهل ما يقولون صحيحًا؟","title":"حكم تشخيص الرقاة للمصابين","answer":"الجواب:\n\nإذا كان طالب العلم الذي يرقي الناس قد اعتاد علامات يعرفها مما يصيب المسحور، أو علامات يعرف بها العين؛ فلا بأس بذلك، يقرأ عليه ما يسر الله من كتاب الله، كالفاتحة، وآية الكرسي، وقل هو الله أحد، والمعوذتين، أو غيرها من الآيات، الله جعل القرآن شفاء من العين، ومن السحر أيضًا، حتى قال ﷺ: لا رقية إلا من عين أو حمة. \n\nقال العلماء: معنى لا رقية أولى وأشفى، أو لا أولى وأنفع إلا من عين أو حمة، والعين هي النظرة يسمونها النظرة، هي النفس، والحمة السم من ذوات السموم، وقال -عليه الصلاة والسلام-: لا بأس بالرقى ما لم تكن شركًا وقد رَقى ورُقي -عليه الصلاة والسلام- وأمر أن يرقى أولاد جعفر وقال: إنها أصابتهم العين قال لأمهم: إنها أصابتهم العين فأمرها أن تسترقي لهم، فالرقية نافعة من العين. \n\nفإذا كان طالب العلم المعروف بالعقيدة الصالحة أنه جرب هذه الأمور، ورأى أن ما في فلان أنه مما يعرف أنه عين، أو أنه سحر، مسحور، فيتعاطى بعلاج السحر، أو علاج العين، النبي  قال: العين حق، ولو أن شيئًا سبق القضاء؛ لسبقته العين وقال: استغسلوا فإذا عرف العائن يستغسل، يطلب منه أن يغسل وجهه، ويتمضمض، ويغسل داخلة إزاره، وأطراف يديه ورجليه، حتى يصب على المعين، وهو يشفى بإذن الله، أو يرفع بما يسر الله من القرآن، من الفاتحة، وآية الكرسي، وغير ذلك، والغالب أنه ينفعه ذلك بإذن الله.\n\nوهكذا المسحور يرقى بالفاتحة، وآية الكرسي، وآية السحر التي في سورة الأعراف، ويونس، وطه تقرأ في ماء له مع القواقل -قل يا أيها الكافرون، قل هو الله أحد، والمعوذتين- ويشرب منه بعض الشيء، ويغتسل بالباقي، فينفع الله بذلك كثيرًا ممن يصاب بالسحر.\n\nوالسحر واقع يقع كثيرًا، كما قال الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ [البقرة:102]. \n\nفالسحر واقعن وكثير من الناس منه ما يقتل، ومنه ما يمرض، ومنه ما يغير العقل، لهم فيه أنواع من التصرفات، فيستعينون بالجن والشياطين في ذلك، وقد وقع هذا في عهد موسى -عليه الصلاة والسلام- وقام سحرة فرعون بجمع العصي، والحبال  على أعين الناس، وسحروا أعينهم؛ حتى ظن الناس أن هذه العصي، وهذه الحبال حيات يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فلما ألقى موسى عصاه لقفتهان وأخذتها كلها، وعرف الناس بطلان هذا السحر، وخر السحرة سجدا لله  وتابوا وأنابوا إلى الله .\n\nوالمقصود: أن هذا له علاج، فإذا عرف بالعلامات التي اعتادها أنه سحر؛ استعمل الرقية من السحر، وذكر بعض المتقدمين أن من أسباب العلاج، وأن مما يدخل في العلاج سبع ورقات سدر، تدق وتجعل في الماء أيضًا، وأن هذا أيضًا قد ينفع بإذن الله من أمر السحر.\n\nوهكذا في أمر الرجل الذي يحبس عن زوجته، ويمنع من زوجته إذا قرئ له هذه الآيات مع الفاتحة، مع آية الكرسي، مع قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، وشرب منه، واغتسل بالباقي، فالغالب أنه يزول أثره ويطلق حبسه.","link":"https://binbaz.org.sa/fatwas/3221/حكم-تشخيص-الرقاة-للمصابين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1432.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":7806,"question":"سماحة الشيخ يقول السائل مصري ومقيم بتبوك: ما هي الحدود والضوابط في الرقية الشرعية؟ وهل يجوز للراقي أن يرقى مجموعةً من الأشخاص في وقت واحد؟ وبماذا تنصحون المرضى مأجورين؟","title":"ما هي ضوابط الرقية الشرعية؟","answer":"الجواب: الرقية تكون بالقرآن وبالدعوات الطيبة هذه الرقية، مع رجاء أن الله يتقبل وينفع بها فينفث عليها بريقه ويقرأ الفاتحة أو بعض الآيات أو آية الكرسي أو قل هو الله أحد والمعوذتين القرآن كله شفاء، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44].\nفالرقية تكون بالقرآن وبالدعوات الطيبة على محل الألم، ينفث على محل الألم في صدره أو رأسه أو يده أو رجله ويقرأ الفاتحة وما تيسر معها من القرآن ويدعو: (رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاءً لا يغادر سقما)، ويقول: (باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك)، هذه الرقية الشرعية، مع رجاء أن الله ينفع بذلك، وسؤاله أن يتقبل وأن ينفع وأن يشفي المريض، يكون عنده إيمان بأن الله هو الشافي وأن هذه أسباب، فهو يسأل الله أن يشفي المريض ويقرأ عليه، ويرجو من الله أن ينفع برقيته.\nيجوز أن يرقي أشخاص اثنين ثلاثة قدامه ينفث على هذا وهذا ويقرأ لا بأس إذا استطاع ذلك يكون اثنين أو ثلاثة قدامه ينفث عليهم على صدورهم أو في أيديهم أو على رءوسهم على حسب المرض لا بأس ما هو بشرط واحد، لو كان اثنين قدامه أو ثلاثة نفث على هذا وهذا لا حرج فيه، لا نعلم في هذا حرج. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5197/ما-هي-ضوابط-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05115.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":7825,"question":"سماحة الشيخ يقول السائل مصري ومقيم بتبوك: ما هي الحدود والضوابط في الرقية الشرعية؟ وهل يجوز للراقي أن يرقى مجموعةً من الأشخاص في وقت واحد؟ وبماذا تنصحون المرضى مأجورين؟","title":"ما هي ضوابط الرقية الشرعية؟","answer":"الجواب: الرقية تكون بالقرآن وبالدعوات الطيبة هذه الرقية، مع رجاء أن الله يتقبل وينفع بها فينفث عليها بريقه ويقرأ الفاتحة أو بعض الآيات أو آية الكرسي أو قل هو الله أحد والمعوذتين القرآن كله شفاء، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44].\nفالرقية تكون بالقرآن وبالدعوات الطيبة على محل الألم، ينفث على محل الألم في صدره أو رأسه أو يده أو رجله ويقرأ الفاتحة وما تيسر معها من القرآن ويدعو: (رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاءً لا يغادر سقما)، ويقول: (باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك)، هذه الرقية الشرعية، مع رجاء أن الله ينفع بذلك، وسؤاله أن يتقبل وأن ينفع وأن يشفي المريض، يكون عنده إيمان بأن الله هو الشافي وأن هذه أسباب، فهو يسأل الله أن يشفي المريض ويقرأ عليه، ويرجو من الله أن ينفع برقيته.\nيجوز أن يرقي أشخاص اثنين ثلاثة قدامه ينفث على هذا وهذا ويقرأ لا بأس إذا استطاع ذلك يكون اثنين أو ثلاثة قدامه ينفث عليهم على صدورهم أو في أيديهم أو على رءوسهم على حسب المرض لا بأس ما هو بشرط واحد، لو كان اثنين قدامه أو ثلاثة نفث على هذا وهذا لا حرج فيه، لا نعلم في هذا حرج. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5197/ما-هي-ضوابط-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05115.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":8153,"question":"المستمع محمد عبد الله عبد الرحمن الثنيان من الزلفي يقول في رسالته: بعض الناس يعلقون رجل الذئب على رقاب أبنائهم أو ذويهم، ويعتقدون أنه يذهب الجنون، فما رد فضيلتكم على هذا وفقكم الله؟","title":"حكم تعليق التمائم والحروز","answer":"الجواب: هذا من الخرافات؛ تعليق رجل الذئب أو إذنه أو ضرسه أو شيء من شعره على المريض أو على غير المريض للصيانة والحفظ كل هذا منكر، كله خرافات لا أصل له، وهذا من التمائم التي حرمها الله جل وعلا، وسماها النبي شرك عليه الصلاة والسلام، يقول النبي ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق شيء فقد أشرك فتعليق التمائم لا يجوز، سواء كانت التمائم من رجل الذئب أو من شعره أو من عظامه أو من غير هذا من الحيوانات الأخرى أو حديدة أو شيء مقروء في ورقة يجعل في ورقة أو في رقعة أو غير ذلك يعلق على الطفل أو على المرأة أو على المريض كل هذا لا يجوز؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه، وأخبر أنه من الشرك وقال: من تعلق تميمة فلا أتم الله له.\nوكان في الجاهلية تعلق التمائم يسمونها: الحروز، يسمونها: الحجب، يسمونها: الجوامع، تعلق على المريض وعلى الأطفال؛ بزعمهم أنها تدفع العين عنهم أو تدفع الجن، وهذا لا يجوز بل هو منكر يجب إزالته، فلا يجوز تعليق تميمة من عظام الذئاب أو من شعر الذئاب أو من رجل الذئب أو الضبع أو الأسد أو النمر أو غير ذلك، ولا يجوز تعليق أيضاً تمائم من القرآن، يجعل الورقة يكتب فيها شيء ويعلقها في قطعة جلد أو غير ذلك، أو مسامير أو غير ذلك مما يفعله بعض الناس أو طلاسم؛ حروف مقطعة يجعلونها في خريقات ثم يجعلونها في جلد أو غيره تعلق، كل هذا لا يجوز بل يجب الحذر من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5959/حكم-تعليق-التماىم-والحروز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09010.mp3","categories":["الرقى والتمائم"]},{"id":8204,"question":"هذه رسالة أيضاً وردتنا من الزلفي من معهد الزلفي، بعث بها محمد عبد الله عبد الرحمن الثنيان، يقول في رسالته: وجدت بعض الناس إذا أصيب أحد منهم بجن يعلقوا رجل ذئب على يد المصاب، فما مدى صحة ذلك؟ وما رأي فضيلتكم فيه وفقكم الله؟","title":"حكم تعليق التمائم والحروز لدفع العين والمرض","answer":"الجواب: تعليق يد الذئب، أو شعر الذئب، أو عظام الذئب، أو غير ذلك على المريض، أو الذي يظن فيه مس من الجن، أو غير ذلك، هذا لا يجوز، بل هذا من التمائم التي نهى عنها الرسول ﷺ وحذر منها، حيث قال عليه الصلاة والسلام: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له»، «ومن تعلق تميمة فقد أشرك.\nفلا يجوز تعليق التمائم سواءً كانت عظاماً، أو ودع، أو شعر، أو حلقات من حديد، أو غير ذلك، أو من أي جنس، كل هذا لا يجوز، ولا يختص بالذئب، ذئب أو أسد أو كلب أو فهد أو غير ذلك، كل هذا مما لا يجوز، وكله معتبر من التمائم التي نهى الرسول ﷺ عن تعليقها، ولكن يعالج بالقرآن الكريم، يعالج بالقراءة، يعالج بالأدوية الطيبة النافعة، أما التعليق على الأطفال، أو على المرضى، تعليق التمائم من عظام، عظام الذئب، أو رجل الذئب، أو يد الذئب، أو ظلف الذئب، أو شيء من شعر الذئب، أو الكلب، أو الخنزير، أو الأسد، أو غير ذلك كل هذا لا يجوز.\nوهكذا ما يفعل بعض الناس من كونه يضع آيات في قرطاسة، أو يضع معها بعض الدعوات أو بعض المسامير أو بعض الطلاسم، ثم يجعلها في جلد أو في غير ذلك ويعلقها على الطفل أو على المريض، كل هذا لا يجوز.\nالتعليقات التي يراد بها دفع المرض أو دفع الجن، أو دفع العين، كل هذا لا يجوز، والنبي ﷺ: لما رأى على رجل حلقة قال: انزعها فإنها لا تزيدك إلا وهناً، فإنك لو مت وهي عليك ما أفلحت أبداً، وقال: إن الرقى والتمائم والتولة شرك، والرقى يعني المجهولة أو التي فيها أشياء منكرة، وهكذا التمائم، كلها لا تجوز، وهي ما يعلق على الأولاد أو على المرضى عن العين أو عن الجن، كل هذا لا يجوز.\nوهكذا التولة: وهي الصرف والعطف، وهي ما يفعله بعض النساء لتحبيب الأزواج إلى نسائهم، أو تحبيب المرأة إلى زوجها كل هذا لا يجوز، وهو من السحر، هذه كلها محرمة، نبه عليها النبي عليه الصلاة والسلام، وإنما الرقى الجائزة الرقى الشرعية بالقرآن وبالدعوات الطيبة وبما جاء في الأحاديث هذه رقى طيبة، يرقى بها المريض ويدعى له، وينفث عليه ويدعى له طيب، أما كونه يعلق عليه شيء هذا لا يجوز. نعم.","link":"https://binbaz.org.sa/fatwas/6009/حكم-تعليق-التماىم-والحروز-لدفع-العين-والمرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09403.mp3","categories":["الرقى والتمائم"]},{"id":8642,"question":"هذه رسالة وردتنا من السائل صلاح بن أحمد بن الطيب، من السودان من إقليم كردفان الأبيض، يقول: ما حكم من صلى أو أدى أي عبادة من العبادات وبيده تميمة؟","title":"حكم من يصلي وفي يده تميمة","answer":"الجواب: التميمة محرمة ولا تجوز، وهي من الشرك الأصغر، وقد تجر إلى الشرك الأكبر، فصلاته صحيحة إذا كانت تلك التميمة لم يعلق بها قلبه ويعتقد فيها أنها تضر وتنفع؛ يعني لم يقع في الشرك الأكبر، فالشرك الأصغر لا يبطل الأعمال، وإنما الرياء فقط يبطل العمل الذي يقارنه، وأما جنس التميمة إذا علق تميمة في عنقه أو في يده، والتميمة يسميها بعض الناس الحرز، وبعض الناس يسميها الحجاب، ويسميها بعض الناس الجامعة، وهي تتخذ من خرزات أو من عظام، أو من طلاسم -حروف مقطعة- أو من آيات قرآنية، أو من دعوات نبوية، أو غير ذلك، يعلقونها على الأولاد عن العين، وربما علقوها عن الجن، وربما علقوها على الكبير وعلى المريض وكل هذا غلط لا يجوز، ولكن هذا لا يمنع صحة الصلاة، هو مسلم وصلاته صحيحة وهذا غلط منه؛ لأنها من الشرك الأصغر ومما يمنع لكن لا يكون من الشرك الأكبر، ولا يرتقي إلى الشرك الأكبر إلا إذا علق قلبه بها واعتقد أنها تتصرف تشفي وتنفع باستقلالها، ما يعتقد أنها سبب بل يظن أو يعتقد أنها تشفي بنفسها، وهذا اعتقاد عظيم الخطر شرك أكبر، ولكن في الغالب أن المسلم لا يعتقد ذلك، وإنما يظن أنها أسباب، وقد قال النبي ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له ، ومن تعلق تميمة فقد أشرك فالرسول ﷺ بين حرمة هذه التمائم وحرمة تعليقها.\nفالواجب على المؤمن التوبة إلى الله من ذلك إذا فعل هذا، وهكذا المؤمنة عليها التوبة إلى الله من هذا الشيء، وقطع هذه التمائم والحذر منها مطلقا، ولو كانت من الآيات القرآنية، يجب قطعها؛ لأن الرسول ﷺ نهى عن التمائم وحذر منها كلها ولم يستثن شيئاً؛ ولأن تعليق التمائم من القرآن وسيلة إلى تعليق التمائم الأخرى، فالواجب سد باب الشرك وسد ذرائعه، فهذه نصيحتي لكل مسلم: أن الواجب عليه أن يحذر التمائم وهي الحروز فلا يعلقها لا بكتفه ولا برقبته ولا بغير ذلك، لا على ولده، ولا على زوجته، ولا على غير ذلك، بل يعتصم بالله ويتعوذ بكلمات الله التامات من شر ما خلق، ويتعاطى الأذكار الشرعية والأوراد الشرعية والدعوات الطيبة ويكفي ولا حاجة إلى التمائم والحروز، هذا هو الواجب على كل مسلم. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6780/حكم-من-يصلي-وفي-يده-تميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21207.mp3","categories":["صلاة الجماعة","الرقى والتمائم"]},{"id":8645,"question":"هذه رسالة وردتنا من السائل صلاح بن أحمد بن الطيب، من السودان من إقليم كردفان الأبيض، يقول: ما حكم من صلى أو أدى أي عبادة من العبادات وبيده تميمة؟","title":"حكم من يصلي وفي يده تميمة","answer":"الجواب: التميمة محرمة ولا تجوز، وهي من الشرك الأصغر، وقد تجر إلى الشرك الأكبر، فصلاته صحيحة إذا كانت تلك التميمة لم يعلق بها قلبه ويعتقد فيها أنها تضر وتنفع؛ يعني لم يقع في الشرك الأكبر، فالشرك الأصغر لا يبطل الأعمال، وإنما الرياء فقط يبطل العمل الذي يقارنه، وأما جنس التميمة إذا علق تميمة في عنقه أو في يده، والتميمة يسميها بعض الناس الحرز، وبعض الناس يسميها الحجاب، ويسميها بعض الناس الجامعة، وهي تتخذ من خرزات أو من عظام، أو من طلاسم -حروف مقطعة- أو من آيات قرآنية، أو من دعوات نبوية، أو غير ذلك، يعلقونها على الأولاد عن العين، وربما علقوها عن الجن، وربما علقوها على الكبير وعلى المريض وكل هذا غلط لا يجوز، ولكن هذا لا يمنع صحة الصلاة، هو مسلم وصلاته صحيحة وهذا غلط منه؛ لأنها من الشرك الأصغر ومما يمنع لكن لا يكون من الشرك الأكبر، ولا يرتقي إلى الشرك الأكبر إلا إذا علق قلبه بها واعتقد أنها تتصرف تشفي وتنفع باستقلالها، ما يعتقد أنها سبب بل يظن أو يعتقد أنها تشفي بنفسها، وهذا اعتقاد عظيم الخطر شرك أكبر، ولكن في الغالب أن المسلم لا يعتقد ذلك، وإنما يظن أنها أسباب، وقد قال النبي ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له ، ومن تعلق تميمة فقد أشرك فالرسول ﷺ بين حرمة هذه التمائم وحرمة تعليقها.\nفالواجب على المؤمن التوبة إلى الله من ذلك إذا فعل هذا، وهكذا المؤمنة عليها التوبة إلى الله من هذا الشيء، وقطع هذه التمائم والحذر منها مطلقا، ولو كانت من الآيات القرآنية، يجب قطعها؛ لأن الرسول ﷺ نهى عن التمائم وحذر منها كلها ولم يستثن شيئاً؛ ولأن تعليق التمائم من القرآن وسيلة إلى تعليق التمائم الأخرى، فالواجب سد باب الشرك وسد ذرائعه، فهذه نصيحتي لكل مسلم: أن الواجب عليه أن يحذر التمائم وهي الحروز فلا يعلقها لا بكتفه ولا برقبته ولا بغير ذلك، لا على ولده، ولا على زوجته، ولا على غير ذلك، بل يعتصم بالله ويتعوذ بكلمات الله التامات من شر ما خلق، ويتعاطى الأذكار الشرعية والأوراد الشرعية والدعوات الطيبة ويكفي ولا حاجة إلى التمائم والحروز، هذا هو الواجب على كل مسلم. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6780/حكم-من-يصلي-وفي-يده-تميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21207.mp3","categories":["صلاة الجماعة","الرقى والتمائم"]},{"id":8917,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من ليبيا، باعثة الرسالة إحدى الأخوات من هناك تقول: ليلى علي عبدالعزيز ، أستأذن سماحة الشيخ في قراءة رسالة أختنا كاملة لعلها تعطينا صورةً عن شخصيتها وعن سلوكها، تقول:بسم الله الرحمن الرحيم، الحمد لله رب العالمين حمدًا كثيرًا، والصلاة والسلام على أشرف المرسلين سيدنا وحبيبنا محمد وعلى آله وصحابته ومن اهتدى بهديه إلى يوم القيامة، أما بعد:السلام عليكم ورحمة الله وبركاتهأولًا: جزاكم الله الخير كل الخير عنا وعن جميع المسلمين؛ لما تقدمونه من فائدة عظيمة للإسلام والمسلمين، وعسى ربنا أن يوفقكم لمزيد من الخير والصلاح.ثانيًا: مشكلتي هي كما يأتي -تقول عن نفسها-: امرأة محجبة بحمد الله، وأداوم على الصلاة في أوقاتها، وأخاف الله ، وأؤمن بأن الأعمار بيد الله، وكنت عندما أنجب طفلًا يموت فأشار علي بعض الناس بشيء متعارف عليه هنا في ليبيا، وهذا الشيء هو: أن أجمع قطعة نقود من كل بيت يوجد فيه شخص يسمى باسم نبينا ﷺ، أي: أنه يسمى محمد، سواء كان هذا الشخص طفلًا أو صبيًا أو رجل، وتجمع النقود ويشترى بثمنها سوارة تضعها المرأة التي عندما تنجب طفلًا يموت تضعها في يدها، الإسوارة عادةً تكون من الحديد وفعلت ذلك فعلًا فشاء الله  أن يعيش الأطفال الذين أنجبتهم بعد ذلك، فلما رأت أختي الإسوارة وعرفت لماذا وضعتها أنا وعرفت كذلك قصة الإسوارة قالت لي: اخلعيها فورًا من يدك إن هذا شرك صريح بالله ، ولو توفاك الله وأنت تلبسينها باعتقادك أنها تفيدك وتضرك فإنك تموتين وأنت مشركة، فهل هذا صحيح أي: هل يعتبر لبسي لها على هذا الأساس شرك بالله  أم لا؟ وإن كان شرك فكيف أكفر عن ذنبي العظيم هذا؟ وهل صلاتي وصيامي وحسناتي السابقة ذهبت هباءً منثورًا أم لا؟ثالثًا: إذا مكنكم الله من إذاعة رسالتي هذه فأرجو أن تكون الإجابة واضحةً مفصلة؛ لكي أستفيد ويستفيد من يسمعها، جزاكم الله خيرًا؟","title":"حكم تعليق التمائم واعتقاد نفعها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، نبينا محمد وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن هذا الذي فعلتيه أيها السائلة وأرشدك إليه بعض الناس رجاء أن يعيش الولد شيء لا أصل له ولا أساس له بل هو منكر وبدعة ولا دليل عليه، ويسمى مثل هذا: تميمة، والرسول ﷺ نهى عن التمائم وأمر بقطعها، يقول عليه الصلاة والسلام: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، ومن تعلق تميمة فقد أشرك، وبعث عليه الصلاة والسلام في بعض غزواته من يقطع القلائد التي تعلق على الدواب خشية العين وهي الأوتار، وقال: إن الرقى والتمائم والتولة شرك، وهي الرقى التي لا توافق الشرع، والتمائم: ما يعلق على الإنسان خشية العين أو خشية الجن، والتولة: نوع من الصرف والعطف نوع من السحر، فبين ﷺ أنها كلها من الشرك، وفي المسند مسند أحمد رحمه الله بإسناد جيد عن عمران بن الحصين رضي الله تعالى عنهما: أن النبي ﷺ رأى رجلًا في يده حلقة من صفر، فقال: ما هذا؟ فقال: من الواهنة -يعني: علقتها من أجل الواهنة- قال له النبي ﷺ: انزعها فإنها لا تزيدك إلا وهنًا، فإنك لو مت وهي عليك ما أفلحت أبدًا وهذا وعيد عظيم في جعل هذه الحلقة التي يزعم أنه فعلها من أجل الواهنة مرض يأخذ باليد يقال له: الواهنة.\nوجاء عن حذيفة  أنه دخل على رجل قد علق خيطًا في يده فسأله، فقال: من أجل الحمى، فقطعه حذيفة وتلا قوله تعالى: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106].\nوجاء عن إبراهيم النخعي قال: «كان أصحاب ابن مسعود يكرهون التمائم كلها من القرآن وغير القرآن». يعني: يحرمونها.\nوقال سعيد بن جبير التابعي الجليل رحمه الله: من قطع تميمة من إنسان كان كعدل رقبة، كان كأنه أعتق رقبة؛ لأنه خلصه من رق الشرك. وفي الصحيحين من حديث ابن مسعود ، عن النبي ﷺ: أن العبد إذا أكمل في الرحم -يعني: الإنسان إذا أكمل في الرحم مائة وعشرين يومًا- ثلاثة أطوار يرسل إليه ملك فيكتب رزقه وأجله وعمله وشقي أو سعيد فالأمور بيد الله جل وعلا، فقد سبق في علم الله وفي قدره السابق أن أولادك يعيشون بعد الذين ماتوا وليس من أجل السوارة ولكنه ابتلاء وامتحان وقع لك، فعليك التوبة إلى الله جل وعلا والرجوع إليه والندم على ما مضى وهذا شرك أصغر، تعليق التمائم من الشرك الأصغر، لا تحبط معه صلاتك ولا صومك ولا عبادتك السابقة، أعمالك السابقة الطيبة التي لله فعلتيها لا تبطل بهذا؛ لأن هذا شرك أصغر لا تبطل به الأعمال، وإن كنت أردت بهذا السوار وقصدت أنه ينفع ويضر دون لله فهذا شرك أكبر، لكن ليس المسلم يقصد هذا ولا يظن هذا ولا يعتقد هذا، وإنما يعتقد أنها أسباب كما يكفي عن المرض، وكما يتعاطى الأدوية من الحبوب والإبر كلها أسباب، فهكذا تعليق السوارة الذي نعتقد فيك أنك ظننتيها أسبابًا أنها من الأسباب.\nفبكل حال عليك التوبة من ذلك وإن كنت تعتقدين فيها أنها تنفع وتضر فعليك التوبة من ذلك أيضًا والرجوع إليه والتوبة النصوح، ولعل جهلك بذلك يكون شافعًا في سلامة أعمالك الصالحة، والعبد متى تاب أيضًا إلى الله ورجع عن شركه وباطله فإن أعماله الصالحة تبقى له ولا تبطل إلا إذا مات على الكفر بالله ، ولهذا لما أسلم حكيم بن حزام وذكر  عن النبي ﷺ أنه قد سبق منه عتاقه في الجاهلية وصدقة في الجاهلية، فقال له النبي ﷺ: أسلمت على ما أسلفت من خير، والله قال عن الكفار أن أعمالهم إنما تحبط إذا ماتوا على الكفر: إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُوْلَئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلائِكَةِ ... [البقرة:161]الآية، وقال: وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُوْلَئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالآخِرَةِ [البقرة:217] فقيد ذلك بقوله: فَيَمُتْ وَهُوَ كَافِرٌ، فدل ذلك على أن من لم يمت كافرًا بل مات على الإسلام فإن أعماله الصالحة تبقى له ولا تفوت عليه، والحمد لله.\nالمقدم: جزاكم الله خيرًا، شيخ عبدالعزيز! قد يبتلي الله العبد ليبتلي إيمانه ويختبره، لو حصل شيء من هذا -ونتوقع خيرًا- بم توصون أختنا جزاكم الله خيرًا؟\nالشيخ: مثل ما تقدم نوصيها بتقوى الله جل وعلا، والأخذ بالأسباب التي أباحها الله كعرض الطفل على الطبيب أو غير الطفل المصاب بالمرض، وتعاطي الأدوية المباحة والقراءة على المريض والنفث عليه، والكي إذا دعت الحاجة إليه وأشباه ذلك من الأدوية النافعة والأسباب المباحة.\nأما الشيء الذي حرمه الله كتعليق التمائم أو دعاء غير الله، أو الاستغاثة بالجن، أو إتيان الكهان والمنجمين كل هذا باطل لا يجوز، وإنما يجوز للمؤمن الأسباب المباحة والوسائل المباحة فقط، والله  جعل لكل داء دواء، كما في الحديث الصحيح: ما أنزل الله داءً إلا أنزل له شفاء علمه من علمه وجهله من جهله، وقال عليه الصلاة والسلام: لكل داء دواء فإذا أصيب دواء الداء برئ بإذن الله.\nفالمؤمن إذا أصابه شيء يعرضه على أهل الخبرة من الأطباء أو غيرهم من أهل العلم والبصيرة، فإن كان هناك طبيب يعرف هذا الداء عالجه، وإن كان يحتاج إلى قراءة قرأ عليه بعض إخوانه المسلمين وعالجوه بالقراءة والدعاء، هكذا المشروع، أما أن يعلق حديدة أو طاسةً أو خشبةً أو شيئًا يقرأ فيه في رقعة ويعلق كل هذا ما يجوز حتى ولو من القرآن على الصحيح، وإن كان بعض السلف خالف في ذلك فإن الصحيح الذي عليه المحققون: أن تعليق التمائم لا يجوز ولو كان من القرآن سدًا للذريعة؛ وعملًا بالعموم الوارد في الأحاديث التي فيها النهي عن التمائم والتحذير منها ولم يفصل عليه الصلاة والسلام، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7074/حكم-تعليق-التماىم-واعتقاد-نفعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_171/17101.mp3","categories":["الرقى والتمائم"]},{"id":8984,"question":"هنا رسالة مطولة من صفحتين من القطع الكبير وبعثت بها إحدى الأخوات من العراق تقول: الوالدة المعذبة علية علي جواد أختنا تشكو حالة ابنها الصحية حيث أنه كلما قرب الاختبار اعتراه كثير من الأمراض، وترجو التوجيه ولاسيما أنها تخشى الذهاب إلى المشعوذين والكهان؟","title":"دور الأم تجاه ولدها المريض","answer":"الجواب: نوصي بالدعاء له بالعافية أن تدعو له كثيرًا في صلاتها في سجودها في تشهدها قبل السلام، تدعو له بالعافية والشفاء، وتعرضه على الأطباء المختصين في مثل هذا المرض من علماء النفس وغيرهم، وتوصي أيضًا من يقرأ عليه من خواص الطيبين يقرءون عليه لعل الله يشفيه في ذلك، قد تكون هذه نفسًا وهي اللي يسمونها العين، قد تكون.. والقراءة ينفعه الله بها في هذا الشيء، فإذا تيسر من الناس الطيبين من يقرءوا عليه فهذا إن شاء الله يكون سببًا للشفاء، وهكذا عرضه على بعض الأطباء الطيبين من علماء النفس، أو علماء مثل هذا المرض الذي يعتري الناس فإذا تيسر من يعالجه فالحمد لله وإلا فالقراءة كافية، يقرأ عليه مع الدعاء، أما الذهاب إلى المشعوذين فلا يجوز، الكهان الذين يخدمون الجن ويسألون الجن ويدعون علم الغيب هؤلاء لا يجوز إتيانهم ولا سؤالهم بل يجب البراءة منهم والحذر منهم، لقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح.\nوقال عليه الصلاة والسلام: من أتى كاهنًا أو عرافًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فالواجب على كل مؤمن وعلى كل مؤمنة الحذر مما حرم الله ورسوله والاكتفاء بماشرع الله، ونسأل الله له الشفاء والعافية، نسأل الله أن يمن عليه بالشفاء وأن يخلصه مما أصابه، وأن ييسر له العلاج الصالح الناجع إنه سميع قريب.\nالمقدم: جزاكم الله خيرًا، إذًا سماحة الشيخ لا ترون أن هناك محظورًا في عرضه على بعض الثقات كيما يقرأ عليه أو كذا؟\nالشيخ: نعم.\nالمقدم: ولا يعد هذا أيضًا من الذهاب إلى ما أسميتم بالمشعوذين؟\nالشيخ: لا، تلتمس الناس الطيبين المعروفين بحسن العقيدة والقراءة على المرضى لعل الله أن ينفعه بذلك؛ لأن القراءة على المرضى نافعة، الله جعل في القرآن شفاء، والنبي ﷺ قال: اعرضوا علي رقاكم لا بأس بالرقى ما لم تكن شركًا، ورقى النبي ورقي عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/7142/دور-الام-تجاه-ولدها-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17409.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":9019,"question":"مستمعة من الكويت تقول: (ف. م. ص) أختنا تقول: إني أحب برنامجكم وأستمع إليه كثيراً، فهل تقبلون مني هذه الرسالة وتجيبون على أسئلتي؟السؤال الأول: هل يجوز وضع القرآن تحت وسادة الطفل وتعليق الجامعة على الرقبة؟","title":"حكم وضع المصحف تحت الوسادة، وتعليق الحروز على الرقبة","answer":"الجواب: لا يجوز وضع القرآن تحت الوسادة، لا للطفل ولا لغيره؛ لأن هذه إهانة للقرآن، ولأن هذا اعتقاد من قائله أنه يمنع عن الطفل أو غيره وهذا غلط لا أصل له، إنما الذي يمنع بإذن الله التعوذات الشرعية، كون أمه أو أبوه يعوذه، يقول: أعيذك بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة، كما كان النبي ﷺ يعوذ الحسن والحسين بهذا التعوذ، يقول: أعيذكما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة أما وضع المصحف تحت الوسادة للطفل أو للكبير هذا لا يجوز؛ لأنه إهانة لكتاب الله واعتقاد فاسد لا أصل له، وهكذا تعليق الجامعة، تعليق آيات أو حروز في رقبة الطفل أو الكبير أو المريض هذا لا يجوز أيضاً؛ لأنه من باب تعليق التمائم التي نهي عنها، يقول النبي ﷺ: من تعلق تميمة فلا أتم الله له، من تعلق تميمة فقد أشرك، فلا يجوز تعليق التمائم وهي: الحروز التي تتخذ من آيات قرآنية تكتب أو من ودع أو من عظام أو من غير هذا مما يفعله بعض الناس حتى ولو من الآيات القرآنية على الصحيح لا يجوز تعليقها، إنما القرآن يتلى للشفاء، ينفث بها المريض، يقرأ على المريض لطلب العافية من الله عز وجل، أما كونه يعلق على رقبته أو في عضده سواء كان كبيراً أو صغيراً هذا لا يجوز، وهذا من التمائم التي حرم الله جل وعلا اتخاذها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7177/حكم-وضع-المصحف-تحت-الوسادة-وتعليق-الحروز-على-الرقبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14712.mp3","categories":["الرقى والتمائم"]},{"id":9087,"question":"الرسالة الأولى وردت إلى البرنامج من المستمع عبد الفتاح أحمد محمد عطية مصري الجنسية ومقيم بالقصيم في الفوارة، يقول في رسالته: عن عمران بن حصين رضي الله عنه: أن النبي ﷺ رأى رجلاً في يده حلقة من صفر، فقال: ما هذه؟ قال: من الواهنة، فقال: انزعها فإنها لا تزيدك إلا وهناً، فإنك لو مت وهي عليك ما أفلحت أبداً وأيضاً: أسمع أن من الشرك لبس الحلقة والخيط ونحوهما لرفع البلاء أو دفعه، فما معنى: الحلقة والخيط والوهن؟ وما هو الشرك، أفيدونا أفادكم الله؟","title":"حكم الحلقة والخيط التي تستعمل لدفع المرض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله، وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله، واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفهذا الحديث الذي ذكره السائل: وهو حديث عمران بن حصين بن عبيد الخزاعي رضي الله عنه عن أبيه رواه الإمام أحمد بن حنبل في المسند بإسناد جيد، ورواه غيره: أن رجلاً كان في يده حلقة علقها من أجل الواهنة من أجل مرض يقال له: الواهنة، وهو مرض يأخذ باليد من المنكب يحصل له بها ضعف، فكانت الجاهلية تعلق هذه الحلقة تزعم أنها تنفع من هذا المرض: فقال النبي ﷺ -لما رآها على هذا الرجل، وفي رواية: أنه رآها على عمران نفسه-: انزعها فإنها لا تزيدك إلا وهناً، فإنك لو مت وهي عليك ما أفلحت أبداً.\nقوله: انزعها يعني: أزلها، وقوله: فإنها لا تزيدك إلا وهناً يدل على أن هذه العلاجات غير المشروعة لا تزيد صاحبها إلا وهناً إلا مرضاً على مرضه وشراً على شره: فإنك لو مت وهي عليك ما أفلحت أبداً وما ذاك إلا لأنها نوع من التمائم التي يعلقها الجهلة، وهي نوع من الشرك؛ لأنها تعلق القلوب على غير الله، وتلفتها إلى غير الله، فلهذا أنكرها الشارع ونهى عنها، وفي هذا الباب يقول ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له: ومن تعلق تميمة فقد أشرك.\nوالتمائم: هي ما يعلق على الأولاد وعلى المرضى من ودع أو طلاسم أو عظام أو غير هذا مما يعلقه الجهلة، يزعمون أنها تشفي المريض، وأنها تمنعه من الجن أو من العين، وكل هذا باطل لا يجوز فعله، وهو من الشرك الأصغر، وما ذاك إلا لأنها تعلق القلوب على غير الله، وتجعلها في إعراض وغفلة عن الله عز وجل، والواجب تعليق القلوب بالله وحده، ورجاء الشفاء منه  وسؤاله والضراعة إليه في طلب الشفاء؛ لأنه المالك لكل شيء وهو النافع الضار، وهو الذي بيده الشفاء ، فلهذا شرع الله عز وجل ترك هذه التعاليق وشرع النهي عنها، حتى تجتمع القلوب على الله وعلى الإخلاص له والتوكل عليه وسؤاله الشفاء سبحانه وتعالى دون كل ما سواه، فلا يجوز للمسلم أن يعلق حلقة من حديد، ولا من صفر، ولا من ذهب ولا من غير ذلك، لقصد الشفاء، أو من عظام في اليد أو نحو ذلك، ومن هذا الأسورة الجديدة التي يستعملها بعض الناس، المعدنية، هي من جنس هذا؛ يجب منعها.\nيقول بعضهم: أنها تمنع من الروماتيزم، وهذا شيء لا وجه له، بل يجب منعها كالحلقة التي علقها عمران ، وهكذا ما يعلق من عظام أو من شعر الذئب أو من ودع أو من طلاسم وأشياء مجهولة، كل هذا يجب منعه وكله داخل في قوله ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له ولما دخل حذيفة على رجل مريض ووجده قد علق خيطاً قال: ما هذا؟ قال: من الحمى، فقطعه وتلا قوله تعالى: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106].\nفلا يجوز للمسلم أن يعلق خيوطاً ولا حلقات، ولا تمائم، ولا غير ذلك، بل يجب أن يبتعد عن هذه الأمور التي كانت تعتادها الجاهلية، ويلتزم بأمر الإسلام الذي فيه الهدى والنور، وفيه الصلاح والإصلاح، وفيه العاقبة الحميدة والله ولي التوفيق.\nالمقدم: وأيضاً في سؤاله يسأل عن معنى الشرك؟\nالشيخ: الشرك شركان: أكبر وأصغر، فالشرك الذي يكون بسبب تعليق التميمة والحلقة شرك أصغر؛ لأنه يصرف القلوب إلى غير الله، ويعلقها بغير الله، فصار نوع شرك من هذه الحيثية، وهو من أسباب الغفلة عن الله وعدم كمال التوكل عليه ، وصار هذا نوعاً من الشرك، ولهذا قال النبي ﷺ: من تعلق تميمة فقد أشرك يعني: قد صرف شعبة من قلبه لغير الله، والواجب إخلاص العبادة لله وحده والتعلق عليه سبحانه وتعالى، والواجب التوكل عليه أيضاً جل وعلا، وأن يكون قلبك معلقاً بالله ترجو رحمته وتخشى عقابه، وتسأله من فضله وترجو منه الشفاء .\nأما الأدوية العادية المباحة فلا بأس بها، الدواء بمأكول أو مشروب أو شيء مباح من الحبوب أو من الإبر أو من الضمادات أو ........... كل هذا لا بأس به.\nأما تعليق التمائم وهي الأشياء المكتوبة في قراطيس أو في رقع، أو تعليق قطعاً من الحديد أو قطعاً من الصفر أو من الذهب، أو من الفضة، أو ما أشبه ذلك هذا هو الذي ينهى عنه، ويعتبر تميمة ويعتبر من الشرك.\nوأما الأدوية المعروفة المباحة من مشروب أو مأكول أو ضماد، أو حبوب تؤكل أو إبر تضرب أو ما أشبه ذلك، هذه كلها إذا عرف أنها تنفع لا بأس بها، ولا تدخل في هذا الباب. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7239/حكم-الحلقة-والخيط-التي-تستعمل-لدفع-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_226/22601.mp3","categories":["الرقى والتمائم"]},{"id":9117,"question":"الرسالة التالية وصلت إلى البرنامج من الأخ: محمد أحمد جاد الله سراج سوداني مقيم بالمملكة، يقول في رسالته وفي بدايتها:بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله وبركاته، سؤالي هو: هنالك بعض الفقهاء عندنا في السودان نسمي الواحد منهم فقي أي فقيه، يكتبون الآيات القرآنية في شكل أوراق صغيرة أو حجاب أو على ألواح من الخشب، وتمحى وتشرب حسب المرض، كما أن الحجاب -مثلاً- ضد السلاح أو حفظاً من الشيطان والعوارض، كما تزعم فئة أخرى وغير مجربة لها بأنها أسحار، كما أن هنالك شهود عيان على هؤلاء الفقهاء قد عالجوا مئات من المجانين ومختلي العقول، وتلبس لهم آلاف الحجب يزعمون بأنها ضد السلاح ما رأيكم في هؤلاء أفيدونا أفادكم الله؟","title":"بيان ما يجوز ويحرم من الرقى والتمائم","answer":"الجواب: هذا الكلام فيه تفصيل، فطالب العلم أو من يسمى فقيهاً إذا كتب آيات من القرآن في ورقة أو صحن بالزعفران أو بالعسل ونحو ذلك حتى يغسلها المريض ويشربها هذا أجازه كثير من أهل العلم وذكره العلامة ابن القيم رحمة الله في زاد المعاد في هدي خير العباد عن جماعة من أهل العلم من السلف، وذكره غيره أيضاً فالأمر فيه واسع وسهل، إذا كتب آيات من القرآن أو دعوات طيبة بالزعفران أو بالعسل ثم غسل وشربه المريض قد ينفع الله بذلك، ولكن أحسن من هذا أن يقرأ على المريض، ينفث عليه بالآيات والدعوات الطيبة يسأل الله له الشفاء هذا أحسن، وإن قرأ في الماء وشربه المريض أو رش عليه به نفع بإذن الله أيضاً.\nأما الحجب وهي ما يكتب في أوراق تعلق على المريض، كأن يكتب آيات تعلق على المريض ضد السلاح أو ضد الجن فهذا لا يجوز، وإن أجاز بعض أهل العلم تعليق القرآن.. بعض أهل العلم جاز تعليق الآيات ولكنه قول ضعيف ومرجوح، والصواب: أن الحجب لا يجوز اتخاذها لا من الآيات ولا من غير الآيات، أما من غير الآيات كالعظام والودع والطلاسم والأسماء المجهولة، هذا لا تجوز بغير شك؛ لأن الرسول عليه السلام قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعةً فلا ودع الله له، ومن تعلق تميمةً فقد أشرك ولأنها من أعمال الجاهلية ولأنها تصد القلوب عن الله وتعلقها بغيره، والقلوب يجب أن تعلق بالله  وتعتمد عليه، فتعليق هذه التمائم يجعل القلوب تميل إليها وتتعلق بها وترتاح لها وهذا خطر عظيم، فلا يجوز تعليق التمائم وهي الحجب وتسمى الجوامع ولها أسماء عند الناس.\nومن هذا ما ورد في حديث عمران بن حصين رضي الله عنه عن النبي ﷺ أنه رأى رجلاً في يده حلقة من صفر فقال: ما هذا؟ قال: من الواهنة، فقال له النبي ﷺ: انزعها فإنها لا تزيدك إلا وهناً فإنك لو مت وهي عليك ما أفلحت أبداً فأخبر النبي ﷺ أن هذه الحلقة التي يعلقها بعض الناس في يده عن مرض يسمى الواهنة لا تزيده إلا وهناً، وأنها منكرة لا تجوز، فهي من جنس التمائم وقد أخذ حذيفة بن اليمان رضي الله عنه الصحابي الجليل على رجل فوجد في يده خيطاً من الحمى فقطعه، سأل عن هذا قال: من أجل الحمى، فقطعه وتلا قوله سبحانه: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106].\nفهذا يدل على أن عمل الصحابة إنكار هذا الشيء والنهي عنه، فلا يجوز لمسلم ولا لمسلمة تعليق هذه التمائم ولا هذه الخيوط والحجب على مريض أو على صبي أو على غيرهما لدفع الجن أو السلاح أو ما أشبه ذلك؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وبين أن تعليق التمائم لا يجوز، ولم يفصل بين تميمة وتميمة ولم يقل: إلا من القرآن بل عمم، فدل ذلك على أن التمائم كلها من القرآن وغير القرآن ممنوعة؛ لأن الرسول عمم في النهي عليه الصلاة والسلام وهو المشرع وهو أنصح الناس للناس، ولو كان في التمائم شيء مستثنى لاستثناه النبي عليه الصلاة والسلام، ثم أيضاً تعليق التمائم من القرآن وسيلة إلى تعليق التمائم الأخرى، فيلتبس الأمر ويخفى على الناس وتنتشر التمائم الشركية وسد الذرائع من أهم المهمات للشريعة الإسلامية. فوجب منع التمائم كلها عملاً بعموم الأحاديث وسداً لذرائع الشرك، وحماية للأمة مما يفسد عقيدتها ويسبب غضب الله عليها سبحانه وتعالى نسأل الله للجميع الهداية والتوفيق.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7282/بيان-ما-يجوز-ويحرم-من-الرقى-والتماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/28807.mp3","categories":["الرقى والتمائم"]},{"id":9319,"question":"له سؤال أخير أيضاً، يقول: ذهبت إلى محافظة أخرى في بلادنا وسألت بعض علماء الدين حول هذا الأمر، فقالوا لي: ضع مصحفاً في بيتك وآية للرسول ﷺ فلا يصيبك إثم ولا ذنب؟","title":"حكم وضع المصحف في البيت حرزاً من الشياطين","answer":"الجواب: هذا لا أصل له، هذا غلط، وضع المصحف لا يمنع من الأدواء، إنما أنزل الله المصحف لقراءته والعمل به، لا ليجعل حرزاً للبيوت، هذا كله لا أصل له، وهكذا قوله: آية للنبي صلى الله عليه وسلم، هذا كلام لا معنى له، وايش معنى آية للنبي؟ يعني: آية فيها ذكر النبي ﷺ؟ المصحف كله فيه ذكر النبي ﷺ، المقصود أن هذا غلط، وشيء لا وجه ولا أصل له، وليس وضع المصحف في البيت حرزاً للبيت، وإنما الحرز للبيت التعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات .. باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباحاً ومساءً، هذا ينفع الله به كما قاله النبي ﷺ، الإنسان يتعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات صباحاً ومساء يقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات.\nكذلك يقرأ آية الكرسي عند النوم وبعد كل صلاة، هذا من أسباب العافية والحفظ، كذلك يقرأ قل هو الله أحد والمعوذتين بعد كل صلاة، هذا من أسباب العافية والحرز، ويقرؤها بعد صلاة المغرب ثلاثاً، وبعد صلاة الفجر ثلاثاً، وعند النوم يقرأ قل هو الله أحد والمعوذتين، وكل هذا من أسباب حفظ الله للعبد وتسليمه إياه من شر أعدائه من الشياطين وغيرهم.\nوأما المصحف الذي يوضع في دولاب أو في فرجة أو في محل في البيت ليس هذا حرزاً وإنما الحرز والسبب العظيم هو استعمال ما شرعه الله سبحانه وتعالى من أدعية وقراءة. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7488/حكم-وضع-المصحف-في-البيت-حرزا-من-الشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23706.mp3","categories":["الرقى والتمائم"]},{"id":9815,"question":"يسأل أيضاً ويقول: هناك عرق للعقرب إذا لبسه بعض الأشخاص يخدر العقرب فلا تستطيع لدغ ذلك الشخص اللابس له، فهل تعليقه يكون من التمائم المنهي عنها؟","title":"حكم تعليق شيء لدفع ضر","answer":"الجواب: نعم تعليق ما يمنع يكون من التمائم، سواء زعم أنه يمنع العقرب أو يمنع الحيات أو يمنع الحمى أو يمنع غير ذلك، الرسول ﷺ نهى عن التعاليق، وقال عليه الصلاة والسلام: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي الرواية الأخرى: «من تعلق تميمة فقد أشرك» .\nفالمقصود: أن التعاليق لا تجوز ضد الحمى وضد العقارب وضد الحيات أو ضد السباع أو ما أشبه ذلك يعتقد فيها أنها تدفع، ... أن هذه الحلقة أو هذه العقدة المعينة من قطن أو صوف أو غير ذلك، أو أن هذا الخاتم يمنع أو ما أشبه ذلك، كل هذا لا يجوز، وهذا من عمل الجاهلية.\nولكن يتعاطى ما شرع الله كالتعوذ بكلمات الله التامات من شر ما خلق ثلاثاً في الصباح والمساء، ومثل قول: (باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم)، ثلاث مرات في الصباح والمساء، مثل قراءة آية الكرسي خلف كل صلاة بعد الذكر، ومثل قراءة قل هو الله أحد والمعوذتين بعد كل صلاة كل هذا من أسباب السلامة والعافية من الشر.\nأما تعليق خيط أو حلقة أو أي شيء يعلق كخاتم أو سبته أو غير هذا مما يعلق كله لا يجوز، هذا إذا كان لقصد دفع الشرور كالحمى أو العقارب أو الحيات أو ما أشبه ذلك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7986/حكم-تعليق-شيء-لدفع-ضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_260/26007.mp3","categories":["الرقى والتمائم"]},{"id":9923,"question":"وهذه رسالة وردت من (م. ب) من جامعة البترول والمعادن بالظهران يسأل فيها عن أمرين: في الأول يقول: مسألة التداوي؛ فإن بعض أهل العلم قال ما محصلته: أنه لا يجب التداوي من مرض ولو ظن نفعه وتركه أفضل روي عن الإمام أحمد ؛ لأنه أقرب للتوكل، ولخبر الصديق إلى آخره. نرجو بسط القول في هذه المسألة، وما هو خبر الصديق؟ وما رأي سماحتكم؟","title":"حكم التداوي من الأمراض","answer":"الجواب: الصواب في التداوي أنه مستحب ومشروع، ذكره النووي رحمه الله وآخرون عن جمهور العلماء، وأن قول الأكثرين أنه مستحب، وذهب بعض أهل العلم إلى أنه مستوي الطرفين لا يستحب ولا يكره بل هو حلال، وذهب آخرون إلى أن تركه أفضل، ويروى عن الصديق أنه قال لما قيل له: الطبيب؟ قال: الطبيب أمرضني ولكن لا أعلم صحة هذا عن الصديق، ولا أعرف صحة هذا عن الصديق. فالمقصود أن الذي عليه جمهور أهل العلم وهو الصواب أن التداوي مستحب بالأدوية الشرعية المباحة التي ليس فيها حرام كالتداوي بقراءة القرآن والرقية، التداوي بالكي، التداوي عند عدم دواء آخر الكي لا بأس به عند الحاجة، التداوي بأمور مباحة لا بأس بذلك، وقد رقى النبي ﷺ بعض أصحابه، وقد رقاه جبرائيل عليه الصلاة والسلام، فالتداوي لا بأس به، والنبي عليه السلام قال: عباد الله! تداووا، ولا تداووا بحرام فالتداوي أمر مشروع لا بأس به ولا ينافي التوكل، فالتوكل يشمل الأمرين: الاعتماد على الله والتفويض إليه مع تعاطي الأسباب، ولا يجوز للإنسان أن يقول: أنا أتوكل ولا آكل ولا أشرب ولا أتسبب ولا أبيع ولا أشتري ولا أتعاطى زراعة ولا صناعة ولا غيره.. لا هذا غلط، تعاطي الأسباب لا ينافي التوكل، بل هو من التوكل وهكذا التداوي من التوكل، ولهذا أرشد النبي ﷺ إلى التداوي، وسئل عن الرقى والأدوية قال: هي من قدر الله، وقال عمر  لما أتى الشام وبلغه حصول الوباء في الشام الطاعون انصرف بالناس ورجع بهم وقال: نفر من قدر الله إلى قدر الله ثم أبلغه عبد الرحمن بن عوف أن النبي ﷺ قال: إذا سمعتم به في بلد فلا تقدموا عليه فسر بذلك حيث وافق السنة.\nفالمقصود أن التداوي أمر مشروع على الصحيح وهو قول أكثر أهل العلم ومن تركه فلا حرج عليه، وإذا ظن نفعه واشتدت الحاجة إليه تأكد؛ لأن تركه يضر يتعب نفسه ويتعب أهله ويتعب خدامه، فالتداوي فيه مصالح لنفسه ولأهله، ولأن التداوي يعينه على أسباب الشفاء ويعينه على طاعة الله حتى يصلي في المسجد، حتى يقوم بأمور تنفع الناس وتنفعه، فإذا تعطل بسبب المرض تعطلت أشياء كثيرة، وإن كان يثاب عما كان يعمله في حال الصحة في حال المرض كما في الحديث الصحيح يقول ﷺ: إذا مرض العبد أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم هذا من فضل الله جل وعلا، ولكن التداوي فيه مصالح كثيرة إذا كان بالوجه الشرعي والأدوية المباحة هذا هو الصواب، ومن قال: إنه مستوي الطرفين أو إن تركه أفضل فقوله مرجوح والحق أحق بالاتباع، والأدلة الشرعية مقدمة على كل أحد. وفق الله الجميع.\nالمقدم: بارك الله فيكم! سماحة الشيخ! هناك من يحتج في هذا الباب بحديث السبعين ألف الذين يدخلون الجنة بغير حساب.\nالشيخ: هؤلاء ما تركوا الأسباب، إنما تركوا شيئاً وهو الاسترقاء طلب الرقية من الناس تركها أفضل، تركوا الكي وتركه أفضل، لكن عند الحاجة لا بأس؛ النبي عليه السلام قال: الشفاء في ثلاث: كية نار أو شرطة محجم أو شربة عسل وما أحب أن أكتوي وفي لفظ آخر قال: وأنهى أمتي عن الكي وقد كوى ﷺ بعض أصحابه، فإذا دعت الحاجة للكي فلا بأس هو سبب مباح عند الحاجة إليه، والاسترقاء: طلب الرقية، أما إذا رقى من دون سؤال فهو من الأسباب لا بأس به ولا كراهة في ذلك، أما الطيرة في حديث السبعين: لا يسترقون ولا يكتوون ولا يتطيرون الطيرة محرمة وشرك أصغر وهو التشاؤم بالمرئيات أو المسموعات حتى يرجع عن حاجته هذا لا يجوز، وعلى ربهم يتوكلون هذا يشمل المتداوي وغيره، فإن التوكل لا يمنع تعاطي الأسباب، ألست تأكل؟! وألست تشرب؟! الأكل سبب للشبع ولقوام هذا البدن وسلامته وهكذا الشرب فهل يجوز للإنسان أن يقول: أنا لا آكل ولا أشرب وأتوكل على الله في حياتي وأبقى صحيحاً سليماً لا يأكل ولا يشرب هذا لا يقوله عاقل، هكذا يلبس الثياب الثقيلة في الشتاء للدفء لأنه يضره البرد، وهكذا يتعاطى الأسباب الأخرى من إغلاق الباب حذراً من السراق، من حمل السلاح عند الحاجة كل هذه أسباب مأمور بها لا تنافي التوكل، والنبي ﷺ هو سيد المتوكلين في أحد لبس السلاح لبس اللأمة، وفي بدر كذلك، وفي أحد ظاهر بين درعين، لبس درعان وعليه المغفر حين دخل مكة وعليه البيضة في أحد، كل هذه أسباب فعلها ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/8104/حكم-التداوي-من-الامراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26908.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":10177,"question":"المستمع محمد بن محمد سهل بعث يسأل ويقول: هل يجوز وضع مصحف عند الطفل أو تعليقه في السرير؟ جزاكم الله خيراً.","title":"حكم وضع المصحف عند الطفل أو تعليقه في سريره","answer":"الجواب: هذا لا أصل له، إذا كان المقصود من ذلك أنه يكون حرزاً له هذا لا أصل له، ثم أيضاً وضعه عنده قد يعبث فيه ويستهين به لأنه طفل، فلا يجوز وضعه عنده إذا كان يستهين به أو يلعب به، ولا يوضع عنده إذا كان القصد من ذلك أنه يكون حرزاً له من الشياطين أو من الجن، كل هذا لا أصل له، وإنما أهله يسمون عليه، ويعيذونه بكلمات الله التامات من شر ما خلق، كان النبي ﷺ في الليل يعوذ الحسن والحسين عند النوم، يقول: أعيذكما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة، فوالده أو أمه تقول له عند النوم: (أعيذك بكلمات الله التامات من شر ما خلق)، (أعيذك بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة)، أما جعل المصحف عند رأسه أو عند سريره لأجل يكون حرزاً له أو كتابة أوراق تعلق عليه كل هذا لا يجوز، والله المستعان. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8352/حكم-وضع-المصحف-عند-الطفل-او-تعليقه-في-سريره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30813.mp3","categories":["الرقى والتمائم"]},{"id":10708,"question":"يسأل أيضاً ويقول: هل يجوز تعليق بعض الأدعية الواردة في الكتاب والسنة على صدر الرجل أو المرأة، لتكون حرزاً لهم من الجن والشياطين؟","title":"حكم تعليق التمائم من أدعية القرآن والسنة","answer":"الجواب: هذا لا يجوز، تعليق الحروز لا يجوز، لا من القرآن ولا من السنة، ولا من غيرهما، وتسمى: التمائم، وتسمى: الجامعات، وتسمى: الحجب، فلا يجوز تعليقها، يقول النبي ﷺ في هذا المعنى: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، ويقول ﷺ: إن الرقى والتمائم والتولة شرك، فالرقى هي الرقى المجهولة التي لا تعرف أو فيها شرك، وفيها منكر، فهي ممنوعة، والتمائم كذلك ممنوعة كلها وهي ما يكتب في الرقع أو بالقراطيس أو نحوها ثم يجعل في رقعة أو في شيشة يعلق على الطفل أو على المريض، كل هذا لا يجوز، بل هذا من التمائم حتى ولوكان من القرآن، حتى ولو من الأدعية المباحة فإن الصحيح أن التمائم تمنع مطلقاً، لكن من غير القرآن أشد في التحريم، أما القرآن فهو من باب سد الذرائع، فيجب على المؤمن أن يمتنع من ذلك؛ لئلا يقع فيما حرم الله جل وعلا.\nإن الله سبحانه شرع لعباده ما فيه سعادتهم، وفيه نجاتهم، وفيه صلاحهم، ولم يشرع لهم ما فيه ضررهم، بل شرع لهم سبحانه ما فيه الصلاح والسعادة في العاجل والآجل، فليس له أن يبتدع في الدين ما لم يأذن به الله .\nالشيخ: تعيد السؤال؟\nالمقدم: جزاكم الله خيراً، يقول أخونا: هل يجوز تعليق بعض الأدعية الواردة في الكتاب والسنة على صدر الرجل أو المرأة؟\nالشيخ: نعم، مثل ما تقدم؛ لأنها من البدع، فليس له أن يعلقها ولو كانت من القرآن أو من السنة كما تقدم؛ لأن الرسول ﷺ منع من التمائم وتوعد من تعلقها بأن الله لا يتم له، من تعلق تميمة فلا أتم الله له ومن تعلق ودعة فلا ودع الله له.\nفالواجب على المؤمن والمؤمنة التحرز بالأدعية الشرعية لا التعليق، فالمريض يدعى له بالشفاء والعافية، والطفل يدعى له بالشفاء والعافية، ويعوذ يقال: أعوذ بكلمات الله التامة من شر ما خلق عند النوم كما كان النبي ﷺ يعوذ الحسن والحسين يقول لهما: أعيذكما بكلمات الله التامة، من كل شيطان وهامة، ومن كل عين لامة، ويعود أن يعتاد الذكر والدعاء والتعوذ بالله إذا كان يعقل، حتى يتعوذ بنفسه عند نومه، وعند دخوله، وعند خروجه.\nالمقصود ليس هناك حاجة إلى تعليق التمائم، وقد أجاز بعض العلماء تعليق التميمة التي من القرآن، أو من الأدعية المباحة، وقال: إن هذا من جنس الرقية، كما أن الرقية تجوز إذا كانت بالقرآن، والدعوات الطيبة، كذلك التميمة إذا كانت من القرآن، والجواب: أن هناك فرقاً بين هذا وهذا، الرقية جاء فيها .... أن النبي ﷺ رقى ورقي عليه الصلاة والسلام، وقال: لا بأس بالرقى ما لم تكن شركاً، فدل على استثناء الرقية الجائزة، وأنه مستثنى من قوله: إن الرقى والتمائم والتولة شرك؛ لأن الرسول ﷺ رقى ورقي، أما التمائم فلم يرد فيها استثناء، ولم يرد أنه علق تميمة على أحد، فلا يجوز أن تلحق التمائم بالرقى، بل التمائم ممنوعة مطلقاً؛ ولأن تعليق التمائم من القرآن، أو من الأدعية المباحة وسيلة إلى تعليق التمائم الأخرى، ومن يدري أن هذا سليم، وهذا ليس بسليم، فينفتح باب الشرك والتعليق للتمائم الأخرى، والشريعة ..... جاءت بسد الذرائع التي توصل إلى الشرك، فالأحاديث عامة في تعليق التمائم والنهي عن ذلك، وسد الذرائع أمر لازم واجب، فتعين من هذا وهذا منع جميع التمائم مطلقاً، حتى ولو كانت من القرآن، ومن الدعوات المباحة، سداً لذريعة الشرك، وعملاً بالعموم، وحتى يعتاد المؤمن الثقة بالله، والاعتماد عليه، وسؤاله والضراعة إليه أن يعيذه من شر ما يضره، وأن يكفيه شر ما يهمه، وأن لا يعتمد على شيء يعلقه في رقبته أو عضده.\nفالذي جاء به يعني الشرع هو الخير كله، والصلاح كله للصغار والكبار، والمريض وغير المريض، رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8887/حكم-تعليق-التماىم-من-ادعية-القران-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34302.mp3","categories":["الرقى والتمائم"]},{"id":11321,"question":"يسأل ويقول: هل يجوز لبس الورقة الحجاب؟ وهي عبارة عن ورقة من دفتر عادي ويكتب عليها الشخص الذي يدعونه، يكتب عليها آية الكرسي وسورة الفاتحة والمعوذتين جزاكم الله خيرًا.","title":"حكم تعليق التمائم والحروز من القرآن","answer":"الجواب:  تعليق التمائم لا يجوز، لا أوراقًا ولا خرقًا ولا غير ذلك، ما كان النبي ﷺ يفعل ذلك ولم يرشد إلى هذا -عليه الصلاة والسلام- وإنما أرشد إلى القراءة، قراءة القرآن والعلاج بالقرآن بالنفث على ....، بحيث كل إنسان ينفث على نفسه. وكان النبي ﷺ إذا اشتكى نفث في كفيه وقرأ قل هو الله أحد والمعوذتين ثلاث مرات ثم مسح بذلك على ما أقبل من جسده رأسه ووجهه وصدره، أما أن يكتب فيها أوراقًا تعلق هذا لا يجوز، بل هذا من وسائل الشرك والاعتماد على غير الله  ولهذا قال ﷺ: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، ومن تعلق تميمة فقد أشرك. هذه يقال لها: التمائم، ويقال لها: الحروز، ويقال لها: الحجب، ويسميها بعضهم الجامعات، كل هذا لا يجوز، لا يجوز التعليق لا قرآنًا ولا غير قرآن، فإذا كان من غير قرآن صار أشد في الإنكار كالطلاسم أو العظام أو الحديد أو ما أشبه ذلك ، وقد رأى النبي ﷺ على إنسان حلقة من صفر، فقال: ما هذا؟ قال: من الواهنة. قال: انزعها فإنها لا تزيدك إلا وهنًا. فالمقصود أن المؤمن يتجنب هذه الأشياء لا يعلق حديدة ولا ورقة ولا خرقة ولا غير ذلك يرى أنها حرز ينفعه من الجن أو ينفعه من العين، أو ما أشبه ذلك، ويسمونها الحروز، يسمونها التمائم، يسمونها الحجب، كل هذا لا يجوز، والصواب أنها لا تجوز حتى ولو كانت من القرآن، الصواب منعها سدًا للذريعة وعملًا بالأحاديث العامة في منع التمائم والتعليقات، ويليها الشرك الأصغر فإن كان صاحبها يعتقد أنها تدفع عنه الشر بنفسها صار شركًا أكبر أعوذ بالله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9491/حكم-تعليق-التماىم-والحروز-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37702.mp3","categories":["الرقى والتمائم"]},{"id":11966,"question":"يسأل سماحتكم أيضًا عن حكم كتابة الآيات القرآنية، والأحاديث النبوية، وعن حكم تعليقها في المنازل؟ جزاكم الله خيرًا.","title":"حكم كتابة الآيات والأحاديث وتعليقها على الجدران","answer":"الجواب:  أما العناية بحفظ القرآن هذا شيء مطلوب، سنة، وهكذا حفظ الأحاديث كتابتها، الأحاديث الصحيحة ليحفظها، والأحاديث الضعيفة ليعرفها، كأن يكون يكتب ذلك، ويعتني به، هذا طيب، ولكن ينبغي حفظ الأحاديث الصحيحة حتى يعمل بها، أما تعليقها على المريض، أو على الصبيان هذا لا يجوز، لا يجوز تعليق، لا أحاديث، ولا آيات، ولا غيرها، لا على المرضى، ولا على الصبيان، ولا على غيرهم. هذه التمائم التي حرمها الرسول ﷺ ونهى عنها، وقال ﷺ: من تعلق تميمة؛ فلا أتم الله له: من تعلق تميمة؛ فقد أشرك فلا يجوز تعليق التمائم، لا من الآيات، ولا من الأحاديث، ولا من الدعوات الأخرى، ولا من أي مادة، بل ذلك منكر لا يجوز، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10151/حكم-كتابة-الايات-والاحاديث-وتعليقها-على-الجدران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42907.mp3","categories":["الرقى والتمائم"]},{"id":12334,"question":"المستمع عبدالرحمن أحمد يسأل ويقول: تعليق الحجاب على الجسم بقصد أنه ينفع، هل هو حرام، أم حلال، وهي من الآيات، وعليها بعض المربعات؟ إذا كانت حرامًا فهل أدفنها، أم أقوم بحرقها؟ وجهونا جزاكم الله خيرًا.","title":"حكم تعليق الحجب والتمائم من الآيات وغيرها","answer":"الجواب:  تعليق الحجب أمر لا يجوز، سواءً من الآيات، أو من غير الآيات، يقول النبي ﷺ: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة؛ فلا ودع الله له ويقول ﷺ: إن الرقى والتمائم والتولة شرك. التمائم: هي الحجب التي تعلق على الناس. والرقى: هي الرقى الشركية التي لا تعرف معانيها، أو بلسان مجهول، أو فيها إثم، وتوسلات منكرة، أما الرقى الشرعية التي ليس فيها منكر؛ فلا بأس بها أن يرقي أخاه بالآيات وبالدعوات الطيبة. وأما التمائم فهي الحجب لا يجوز تعليقها مطلقًا لا على الرقبة، ولا في العضد، ولا في غير ذلك، ويجب إتلافها بإحراقها، أو دفنها في أرض طيبة إذا كانت آيات، أو إحراقها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10534/حكم-تعليق-الحجب-والتماىم-من-الايات-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45407.mp3","categories":["الرقى والتمائم"]},{"id":12447,"question":"المستمع أحمد علي محمد وحرمه بعثوا برسالة يقولون فيها: إن والدهم توفي، وقد كان يلبس خاتمًا يعتقد أنه يشفي من العقم، وحينئذ كان يلبسه وهو لا يدري أن هذا العمل محرم، ويسألون كيف يتصرفون الآن بعد أن توفي ذلك الرجل، وهو على ذلكم الجهل؟ وبماذا توصونهم؟ جزاكم الله خيرًا.","title":"حكم من مات وهو يلبس خاتماً يعتقد فيه الشفاء جاهلاً","answer":"الجواب:  يدعى له بالعفو والمغفرة؛ لأنه جاهل يحسب أن هذا التعليق ينفع، تعليق الخاتم يحسب أنه ينفع من باب الدواء، ومن باب الطب؛ فلا يضره -إن شاء الله- لو كان حيًا نبه عليه، وأخبر أنه لا يجوز تعليق التمائم، أو تعليق الخواتم، يعتقد فيها أنها من أسباب الشفاء لا تجوز ...... معروف عند أهل العلم. المقصود: أن تعليق خرقه، أو ورقة، أو خاتم، أو حلقة لقصد الشفاء لا يجوز؛ النبي نهى عن هذا -عليه الصلاة والسلام- لكن ما دام جاهلًا؛ فإنه يدعى له بالمغفرة والرحمة، ويصلى عليه، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10654/حكم-من-مات-وهو-يلبس-خاتما-يعتقد-فيه-الشفاء-جاهلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40319.mp3","categories":["الرقى والتمائم"]},{"id":12489,"question":"يقول: إمام المسجد في قريتنا متفرغ للإمامة، ويقوم بكتابة القرآن، وإعطائه للمرضى ليلبسوه، ويسمى بالحجاب، وهذه الإمامة متوارثة، أي عن جد وأب، ونفس العمل أقصد الرقى وكتابة القرآن هو هو مصدر كسبهم، فما هو تعليق سماحتكم على هذا؟ أرجو أن توجهونا، وكيف أتصرف، ولا سيما إذا كان من قرابتي؟ وجهوني جزاكم الله خيرًا.","title":"حكم تعليق التمائم من القرآن","answer":"الجواب:  تعليق القرآن الكريم على المرضى، أو على الأطفال كل ذلك لا يجوز في أصح قولي العلماء، بعض أهل العلم أجاز ذلك، ولكن لا دليل عليه، والصواب أنه لا يجوز تعليق القرآن ولا غيره من الدعوات، أو الأحاديث، لا على الطفل، ولا على غيره من المرضى، ولا على كبير السن؛ لأن الرسول ﷺ نهى عن التمائم، والتمائم: هي ما يعلق على الأولاد، أو على الكبار، وتسمى الحروز، وتسمى الحجب.  فالصواب: أنها لا تجوز لقوله ﷺ من تعلق تميمة؛ فلا أتم الله له من تعلق تميمة؛ فقد أشرك إن الرقى والتمائم والتولة شرك ولم يستثن شيئًا، ما قال: إلا القرآن، بل عمم -عليه الصلاة والسلام- فوجب الأخذ بالعموم، الواجب الأخذ بالعموم. ولأن تعليق القرآن وسيلة إلى تعليق غيره، فإن الناس يتوسلون بالمباحات إلى ما حرم الله، فكيف بشيء لهم فيه شبهة، وقد أفتى بجوازه بعض أهل العلم، فهذا يسبب التساهل، فالواجب الحذر من ذلك.. فالواجب الحذر من ذلك؛ أخذًا بالعموم، وسدًا للذرائع، ذريعة الشرك، فإن تعليق التميمة من القرآن وسيلة إلى تعليق التمائم الأخرى، هكذا الناس لا يقفون عند حد في الغالب، والواجب الأخذ بالعموم، وليس هناك دليل يخص الآيات القرآنية، ويستثنيها، والرسول ﷺ أفصح الناس، وأنصح الناس، ولو كان يستثنى من ذلك شيئًا لقال: إلا كذا وكذا. أما الرقية فلا بأس يرقيه بالقرآن، يرقيه بالدعوات الطيبة رقية كان النبي يرقي -عليه الصلاة والسلام- وقال: لا بأس بالرقى ما لم تكن شركاً فقوله: إن الرقى والتمائم والتولة شرك يعني: الرقى المجهولة، أو الرقى الشركية التي فيها التوسل بغير الله، أو دعاء غير الله، فالرقى المذكورة في هذا الحديث هي الرقى المخالفة للشرع أما الرقى الشرعية؛ فلا بأس بها؛ لقوله ﷺ: لا بأس بالرقى ما لم تكن شركًا. أما التمائم فكلها ممنوعة، سواء كانت من القرآن، أو من غير القرآن، هذا هو الأصح من أقوال أهل العلم. أما التولة فهي السحر، ويسمى العطف، الصرف والعطف، فالسحر لا يجوز كله، ولا يحل لأحد أن يتعاطى السحر، بل يجب الحذر من ذاك، والسحر في الحقيقة لا يتوصل إليه إلا بالشرك، إلا بعبادة الجن، والاستغاثة بهم، وخدمتهم بطاعتهم في معاصي الله، ولهذا قال الله  في حق الملكين: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] فبين أن الملكين يخبران من يتعلم أن تعلم السحر كفر، والله يقول -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فتعليم السحر، وتعلمه منكر عظيم، بل من الشرك الأكبر؛ لأنه لا يتوصل إليه إلا بعبادة الجن، والاستغاثة بهم، والتقرب إليهم بما يرضيهم من الذبائح والنذور، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10700/حكم-تعليق-التماىم-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40611.mp3","categories":["الرقى والتمائم"]},{"id":12507,"question":"يسأل سؤال آخر فيقول: يوجد أشخاص يقومون بتعليق الخرز على عيونهم ورقابهم وآذانهم بسبب الأمراض -كما يقول- فهل هذا شرك يخرج من الملة، أم ماذا؟ جزاكم الله خيرًا.","title":"هل تعليق الحروز شرك يخرج من الملة؟","answer":"الجواب: هذا من الشرك الأصغر، وهو من تعليق التمائم والحروز، سواء أكان خرزًا، أو أوراقًا، أو ودعًا، أو غير ذلك، يقول النبي ﷺ: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي اللفظ الآخر: من تعلق تميمة؛ فقد أشرك. فالتمائم هي: الحروز التي يعلقها بعض الناس، ويقال لها: الحجب، سواء كانت من خرز، أو من ودع، أو من غير ذلك من الأشياء، أو من عظام، أو من أوراق يكتب فيه آيات، أو أحاديث. الصواب حتى ما يكتب من الآيات والأحاديث لا يجوز تعليقه، بل العلاج يكون بالقراءة على المريض، بالقراءة عليه، والدعاء له، أما أن يعلق عليه أوراقًا، أو خيوطًا، أو عظامًا أو خرزًا، أو غير هذا من أجل الشفاء؛ هذا لا يجوز، وهو من الشرك الأصغر، لا يخرج من الملة، ولكنه ينافي كمال التوحيد الواجب، مثلًا: يقول: ما شاء الله، وشاء فلان، لولا الله وفلان، هذا من الشرك الأصغر، مثل: الحلف بغير الله، بالنبي، بالأمانة شرك أصغر، يجب الحذر منه، وقد يكون شركًا أكبر إذا اعتقد صاحبه أن هذه الأمور تنفع بعينها دون الله، وأن تستقل بالنفع دون الله، هذا شرك أكبر، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10707/هل-تعليق-الحروز-شرك-يخرج-من-الملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40702.mp3","categories":["الرقى والتمائم"]},{"id":12541,"question":"يقول في أحد أسئلته: أريد أن أحمل مصحفًا صغيرًا في جيبي، ليحميني من نظرات السوء، وخواطر الشيطان، فهل يجوز ذلك؟ علمًا بأن الإنسان لا يستطيع أن يبقى متوضئًا دائمًا، فهل يصح حمله بدون وضوء، وبدون مسه باليد؟","title":"حكم تعليق القرآن تميمة","answer":"الجواب:  حمله بهذه النية لا يجوز؛ لأن هذا معناه أنك جعلته تميمة، جعلته حجابًا ليقيك العين وغيرها، هذا باطل، ليس حمله مما يقي العين، ولكن تحمله للقراءة لا بأس، تحمله في جيبك حتى تقرأ إذا تيسر في المسجد، أو في بيتك لا بأس، وتحمله بغلاف إذا كنت على غير طهارة، يكون له غلاف تحمله به. أما أن تحمله ليقيك شر العين بزعمك، أو الآفات، هذا غلط هذا باطل، يقول النبي ﷺ: من تعلق تميمة؛ فلا أتم الله له وهذا يعم كل شيء، فليس لك أن تحمل المصحف لهذه النية وهذا القصد، ولكن تحمله لتقرأ فيه، لا بأس بهذا، تقرأ فيه إذا كنت على طهارة، وإذا كنت على غير طهارة؛ يبقى في جيبك حتى تتوضأ وتقرأ، لا بأس، وتحمله بعلاقة أو بغلاف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10746/حكم-تعليق-القران-تميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45609.mp3","categories":["الرقى والتمائم"]},{"id":12571,"question":"يقول: في قريتنا وسائر القرى المجاورة عندما يصيبنا مرض نذهب إلى إمام القرية، ونطلب منه حجابًا، فهل هذا صحيح؟","title":"حكم الاستشفاء بالحجب والمقصود منها","answer":"الجواب:  لا يجوز هذا، هذا عمل منكر، الحجب منكرة وهي التمائم، ويقال لها: الحروز، ويقال لها: الجوامع عند بعض الناس، يسميها: جوامع، وهي منكرة لا تجوز، وليس للإمام أن يعطيكم هذه الحجب؛ لقول النبي ﷺ: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة؛ فلا ودع الله له وفي رواية أخرى: من تعلق تميمةً؛ فقد أشرك. التمائم لا تجوز، وهي الحجب لا يعلقها في عضده، ولا في رقبته، لا الرجل، ولا المرأة، ولا الطفل، ولا الكبير، كل هذا منكر حتى ولو كانت من القرآن، أو من الأدعية المباحة لا يجوز؛ لأن الرسول ﷺ عمم وأطلق، ولم يستثن شيئًا -عليه الصلاة والسلام- ولسد الذريعة أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10773/حكم-الاستشفاء-بالحجب-والمقصود-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45703.mp3","categories":["الرقى والتمائم"]},{"id":12929,"question":"السائلة من ليبيا تقول: تذكر بأنها فتاة متدينة، وتحمد الله على ذلك، تقول السائلة: إذا قرأ الإنسان على نفسه، مثال ذلك: إذا قرأ القرآن وهو مريض من مرض الحسد، هل يفيده، أم لا بد من شخص، أو شيخ يقرأ عليه؟ أفتونا مأجورين.","title":"مشروعية رقية المريض لنفسه","answer":"الجواب:  إذا قرأ الإنسان على نفسه يفيده، كان النبي ﷺ يقرأ على نفسه -عليه الصلاة والسلام- فالمؤمن إذا أحس بمرض، أو ضيق، أو تكدر يقرأ القرآن، يكثر من قراءة القرآن، ويسأل ربه العافية والشفاء، وله بهذا خير عظيم، وله أسوة بالنبي -عليه الصلاة والسلام- يقول الله سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] قالت عائشة -رضي الله عنها-: كان النبي ﷺ إذا اشتكى؛ جمع كفيه، فقرأ فيهما عند النوم: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين ثلاث مرات، يمسح في كل مرة على ما استطاع من جسده، ويبدأ برأسه ووجهه وصدره -عليه الصلاة والسلام- في كل مرة هكذا أخبرت عائشة -رضي الله عنها-.  قالت: وفي مرض موته لما كان لا يستطيع أن يفعل ذلك كنت أقرأ في يديه، وأمسح بهما على وجهه ورأسه وصدره رضي الله عنها. المقصود: أن المؤمن والمؤمنة يقرآن القرآن، ويكثرا من ذلك، وللقارئ بكل حرف حسنة، قارئ القرآن له بكل حرف حسنة، والحسنة بعشر أمثالها. فالوصية لجميع إخواني المسلمين من الرجال والنساء الإكثار من قراءة القرآن في الليل والنهار، وأنت جالس على فراشك، أو في مجلسك، أو في أي مكان، وأنت ماشي في الطريق، تقرأ بينك وبين نفسك، وإذا أحسست بمرض تقرأ في يديك ما يسر الله من القرآن، ومن أهم ذلك سورة قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين، تقرؤهما في يديك ثلاث مرات، وعند النوم أفضل، وتمسح بيديك على ما تيسر من جسدك، وتبدأ برأسك أو وجهك وصدرك ثلاث مرات؛ اقتداءً بالنبي -عليه الصلاة والسلام- وتدعو ربك أن الله يمن عليك بالشفاء والعافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11145/مشروعية-رقية-المريض-لنفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50104.mp3","categories":["الرقى والتمائم"]},{"id":13164,"question":"بعد ذلك نختم رسالة السائلة من سلطنة عمان بهذا السؤال، وتذكر هذه السائلة وتقول: أمي ترتدي التمائم مع أنها مؤمنة بأن ما يريده الله  سيقع، ولكن حسب ما تقول: فالإنسان مطالب بأن يبحث عن عافيته، وصحة نفسه، ولقد نصحناها بأن التمائم شرك وحرام، فنهرتني، وغضبت، علمًا بأن التمائم منتشرة بين أقاربي، ونساء القرية، فما رأيكم بذلك يا سماحة الشيخ؟","title":"حكم تعليق التمائم والحروز","answer":"الجواب:  تعليق التمائم لا يجوز بنص الرسول ﷺ فوصيتي لك ولأمك، ولجميع أهل البلد أن يتقوا الله، وأن يحذروا تعليق التمائم، لا من القرآن، ولا من غيره، يجب قطع التمائم وإزالتها؛ لقول النبي ﷺ: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة؛ فلا ودع الله له، ومن تعلق تميمة؛ فقد أشرك ولقوله ﷺ: إن الرقى والتمائم والتولة شرك فالرقى يعني: المجهولة، أو الرقى بغير الشرع، أما الرقى الشرعية فهي مستثناه غير داخلة في الحديث. والتمائم جمع تميمة، وهي ما يعلق على الأولاد وغيرهم من الحروز من القرآن، أو غير القرآن، أو من ودع، أو من خرازات، أو من طلاسم كل ذلك منكر لا يجوز. وهكذا التولة وهي: تسمى الصرف والعطف، .. نوع من السحر، لا يجوز فعله، لا من النساء، ولا من الرجال، فالسحر من المحرمات، بل من الشرك؛ لقوله -جل وعلا- في السحرة: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] فجعله كفرًا.  فالواجب الحذر من التمائم كلها، من القرآن وغير القرآن؛ لأن تعليقها منكر عمته الأحاديث؛ ولأن تعليق التمائم من القرآن وسيلة إلى تعليق غيرها أيضًا، فالذين أجازوا تعليق التمائم من القرآن قد غلطوا في هذا، والصواب: المنع لأمرين: أحدهما: عموم الأحاديث الدالة على تحريم تعليق التمائم؛ لأن الرسول ﷺ لم يستثن ما قال: إلا إذا كانت من القرآن، بل عمم. المعنى الثاني: أن تعليق التمائم من القرآن لو أجيز؛ لكان وسيلة لتعليق التمائم الأخرى؛ لأن ما كل أحد سيفتش على هذا وعلى هذا، وسد الذرائع أمر لازم، وواجب، نعم. المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11419/حكم-تعليق-التماىم-والحروز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51021.mp3","categories":["الرقى والتمائم"]},{"id":13256,"question":"يقول هذا السائل: ما حكم الشرع في التمائم والرقى؟","title":"حكم التمائم والرقى","answer":"الجواب:  التمائم ممنوعة، وهي ما يعلق على الإنسان، سواء كانت من القرآن، أو غير القرآن، الصواب: منعها، إذا كانت من غير القرآن؛ فلا خلاف؛ تمنع كالطلاسم، أو أشياء منكرة من كتابات منكرة، أو عظام، أو أشياء غير ذلك تعلق هذا منكر. أما إذا كانت من القرآن؛ فاختلف فيها العلماء، والصواب: أنها تمنع أيضًا لأمرين: الأمر الأول: عموم الأحاديث، مثل: قوله ﷺ: من تعلق تميمة؛ فلا أتم الله له .. من تعلق ودعة؛ فلا ودع الله له .. من تعلق تميمة؛ فقد أشرك هذا عام. والأمر الثاني: أنه وسيلة لتعليق التمائم الأخرى، إذا علقت التمائم من القرآن؛ صار وسيلة لتعليق التمائم الأخرى، فإن التمييز بين هذا وهذا فيه صعوبة، فالواجب سد الباب، ومنع التمائم كلها. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11541/حكم-التماىم-والرقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50902.mp3","categories":["الرقى والتمائم"]},{"id":14022,"question":"أيضًا المستمع (م. م. ع) من ليبيا يسأل ويقول: لي والد يكتب للناس من كتب عديدة منها كتاب الرحمة في الطب والحكمة، وكذلك كتب فيها طلاسم ويرسم الواقع شيئًا من تلك الطلاسم في نفس رسالته، ثم إنه يكتب آيات من القرآن الكريم ليتعلقها الناس على أجسامهم، ويرجو توجيهكم سماحة الشيخ، وهل إذا لم يطع والده في هذا الموضوع يعتبر عاقًا؟ أو لا؟","title":"حكم تعليق الطلاسم والحروز","answer":"الجواب: الواجب نصيحة والدك وإخباره أنه لا يجوز تعليق الطلاسم ولا تعليق ما حرم الله  ولا تعليق الآيات؛ لأن هذه من التمائم، والرسول ﷺ قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، ومن تعلق تميمة فقد أشرك، فلا يجوز تعليق الحروز على المريض ولا على الأطفال لا من الطلاسم ولا من الخرز والودع ولا من آيات قرآنية ولا غير ذلك.  الواجب على المؤمن أن يستعمل ما شرعه الله من التعوذات الشرعية مثل: أعوذ بكلمات الله التامات من شر ما خلق، مثل: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، وإذا كان صغيرًا عوذه أهله - أمه وأبوه - يقول له عند النوم: أعيذك بكلمات الله التامات من شر ما خلق، أعيذك بكلمات الله التامات من كل شيطان وهامة ومن كل عين لامة.\nأما تعليق التمائم على الأطفال أو على المرضى فهذا لا يجوز؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام، وهكذا تعليق الطلاسم والأشياء التي لا تعرف لا يجوز ذلك ولا يجوز لوالدك أن يفعل ذلك، وليس لك أن تطيعه فيما حرم الله إنما الطاعة في المعروف. نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12440/حكم-تعليق-الطلاسم-والحروز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61110.mp3","categories":["الرقى والتمائم"]},{"id":14539,"question":"السائل يقول في هذا  هل الصلاة وراء من اعتقد في التمائم التي تكتب من القرآن وتعلق، هل تجوز الصلاة خلف مثل هؤلاء؟جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يجوز تعليق التمائم من القرآن","answer":"الجواب: الصلاة خلفهم صحيحة؛ لأنها مسألة خلافية، التمائم التي من القرآن بعض أهل العلم يجيزها.  والصواب: أنها لا تجوز؛ لأنها وسيلة لتعليق التمائم الأخرى؛ ولأن الأحاديث عامة في النهي عن التمائم في مثل قوله ﷺ: من تعلق تميمة فلا أتم الله له هذا عام، فينبغي ترك التمائم كلها من القرآن وغير القرآن، فلا يعلق تميمة على ولده ولا على بنته ولا على دابته لا من القرآن ولا من غير القرآن، بل يتوكل على الله، ويسأله العافية والشفاء، ويترك تعليق التمائم، سواء كانت من حديد أو من حلق، أو من آيات قرآنية، أو من أحاديث أو من غير ذلك، الأحاديث عامة الرسول ﷺ يقول: من تعلق تميمة فلا أتم الله له، من تعلق تميمة فقد أشرك لكن الصلاة خلفهم صحيحة؛ لأن المسألة خلافية بين أهل العلم، والذي ننصح به الإمام أن يدع هذا الأمر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13035/حكم-الصلاة-خلف-من-يجوز-تعليق-التماىم-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55502.mp3","categories":["صلاة الجماعة","الرقى والتمائم"]},{"id":14865,"question":"يقول: عندي خالة تعمل بالتجارة في السوق، وذهبت إلى أحد الذين يكتبون القرآن للناس، ويقول: هذا مجلب للرزق، ويزيد البيع، وكتب لها ورقة فيها آيات قرآنية، وقال لها: هذه ورقة للمال والأرزاق، هل هذا صحيح أو لا؟","title":"حكم كتابة بعض الآيات لاعتقاد أنها تجلب الرزق","answer":"الجواب: ليس بصحيح، هذا غلط، ولا يجوز فعل هذا، ولا تصديق فاعله، بل هذا من المنكرات والبدع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13365/حكم-كتابة-بعض-الايات-لاعتقاد-انها-تجلب-الرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64508.mp3","categories":["الرقى والتمائم"]},{"id":14877,"question":"مستمع بعث برسالة ضمنها عددًا من الأسئلة، يقول: أنا المستمع (ش. ع. أ) يسأل في أحد أسئلته، ويقول: أرى بعض الناس يكتبون آيات من القرآن، ويربطونها في أعناقهم، ويقولون: هذا حجاب من كذا وكذا، هل هذا مشروع؟ وهل الصحابة فعلوا شيئًا من هذا؟أفتونا، جزاكم الله خيرًا.َ","title":"ما حكم عمل الحروز والتمائم من القرآن؟","answer":"الجواب: هذا ليس بمشروع، وهذا يسمى التميمة، ويسمى الحرز، يسميه بعض الناس الجوامع، وهذا لا يجوز، النبي  قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له فلا يجوز تعليق التمائم، وهي الحروز، وهي أن يكتب آيات، أو دعوات، أو أحاديث، ويعلقها في عنقه، أو في عضده، هذا لا يجوز.  والواجب الحذر من ذلك، أما كونه يتعاطى الورد الشرعي، يقرأ على نفسه عند النوم، ويتعاطى الأوراد الشرعية هذا مطلوب، مأمور به شرعًا، وعند النوم يقرأ آية الكرسي، ويقرأ قُلْ هُوَ اللهُ أحدٌ [الإخلاص: 1] وقُلْ أَعُوذُ بِربِّ الفَلقِ [الفلق: 1] وقُلْ أَعُوذُ بِربِّ النّاسِ، [الناس:1] ثلاث مرات عند النوم، كل هذا من أسباب العافية والسلامة، وكان يفعله النبي ﷺ، ويقول ﷺ لمن قرأ آية الكرسي: إنه لا يزال معه من الله حافظ، ولا يقربه شيطان حتى يصبح. فأنت استعمل هذا، تقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]، تقول أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع العليم ثلاث مرات صباح ومساء، تقرأ قُلْ هُوَ اللهُ أحدٌ [الإخلاص: 1] وقُلْ أَعُوذُ بِربِّ الفَلقِ [الفلق: 1] وقُلْ أَعُوذُ بِربِّ النّاسِ، [الناس:1] ثلاثًا بعد المغرب، وعند النوم، وبعد صلاة الفجر، كل هذا من أسباب السلامة، والحمد لله، والله يغنيك بهذا عن التميمة المكتوبة المعلقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13363/ما-حكم-عمل-الحروز-والتماىم-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64506.mp3","categories":["الرقى والتمائم"]},{"id":15167,"question":"سؤاله الثاني يقول فيه: ما حكم الذي يتعلق خيط لرفع البلاء أو دفعه؟","title":"ما حكم من يعلق خيطًا لرفع البلاء أو دفعه؟","answer":"الجواب: هذا ينكر عليه؛ لأنه من الشرك الأصغر، من جنس التمائم، والنبي  قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي رواية: من تعلق تميمة فقد أشرك ولما دخل حذيفة  على رجل وقد علق عليه خيطًا من الحمى قطعه، قطعه حذيفة، وأنكر عليه، وتلا قوله تعالى: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106] بين له أن هذا من الشرك. فتعليق الخيوط والتمائم من الودع، أو من العظام، أو من شعر الذئب، أو من عظام الذئب أو أسنانه، كل هذا من الخرافات الجاهلية، وهو من المنكرات، وهكذا تعليق الحجب من القرآن يسمونها حجب، ويسمونها حروز، ويسمونها جامعات، كل هذا لا يجوز؛ لأن النبي ﷺ عمم النهي، ولم يستثن القرآن، ولا غيره؛ ولأن استعمال القرآن يفضي إلى استعمال غيره، فينفتح باب الشرك؛ ولهذا قال -عليه الصلاة والسلام-: إن الرقى والتمائم والتولة شرك يعني: الرقى المجهولة التي ليست على الطريقة الشرعية، وهكذا التمائم، وهي ما يعلق على الأولاد عن العين، أو يعلق على النساء، أو المرضى عن الجن، كل هذا منكر، ومن أعمال الجاهلية. والتولة: الصرف والعطف وهو السحر، فبين النبي ﷺ أنه من الشرك؛ لأنه يستعان في ذلك بالجن والشياطين، فالساحر والساحرة إنما يتم لهما ما يتعاطيان من السحر بواسطة عبادتهم الجن والشياطين، وتقربهم إليهم بما يرضيهم. والخيوط من جنس التمائم، إذا علق على يده خيطًا، أو على رقبته يزعم أنه من أسباب الشفاء؛ فهذا من المنكرات يقطع، نعم.","link":"https://binbaz.org.sa/fatwas/13678/ما-حكم-من-يعلق-خيطا-لرفع-البلاء-او-دفعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65908.mp3","categories":["الرقى والتمائم"]},{"id":15175,"question":"سؤاله الثاني يقول فيه: ما حكم الذي يتعلق خيط لرفع البلاء أو دفعه؟","title":"ما حكم من يعلق خيطًا لرفع البلاء أو دفعه؟","answer":"الجواب: هذا ينكر عليه؛ لأنه من الشرك الأصغر، من جنس التمائم، والنبي  قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي رواية: من تعلق تميمة فقد أشرك ولما دخل حذيفة  على رجل وقد علق عليه خيطًا من الحمى قطعه، قطعه حذيفة، وأنكر عليه، وتلا قوله تعالى: وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ [يوسف:106] بين له أن هذا من الشرك. فتعليق الخيوط والتمائم من الودع، أو من العظام، أو من شعر الذئب، أو من عظام الذئب أو أسنانه، كل هذا من الخرافات الجاهلية، وهو من المنكرات، وهكذا تعليق الحجب من القرآن يسمونها حجب، ويسمونها حروز، ويسمونها جامعات، كل هذا لا يجوز؛ لأن النبي ﷺ عمم النهي، ولم يستثن القرآن، ولا غيره؛ ولأن استعمال القرآن يفضي إلى استعمال غيره، فينفتح باب الشرك؛ ولهذا قال -عليه الصلاة والسلام-: إن الرقى والتمائم والتولة شرك يعني: الرقى المجهولة التي ليست على الطريقة الشرعية، وهكذا التمائم، وهي ما يعلق على الأولاد عن العين، أو يعلق على النساء، أو المرضى عن الجن، كل هذا منكر، ومن أعمال الجاهلية. والتولة: الصرف والعطف وهو السحر، فبين النبي ﷺ أنه من الشرك؛ لأنه يستعان في ذلك بالجن والشياطين، فالساحر والساحرة إنما يتم لهما ما يتعاطيان من السحر بواسطة عبادتهم الجن والشياطين، وتقربهم إليهم بما يرضيهم. والخيوط من جنس التمائم، إذا علق على يده خيطًا، أو على رقبته يزعم أنه من أسباب الشفاء؛ فهذا من المنكرات يقطع، نعم.","link":"https://binbaz.org.sa/fatwas/13678/ما-حكم-من-يعلق-خيطا-لرفع-البلاء-او-دفعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65908.mp3","categories":["الرقى والتمائم"]},{"id":15401,"question":"هذا السائل من سوريا، ومقيم في السعودية، يقول: يقوم البعض من الناس بحمل الحجب للدخول على المسؤولين والقضاة، بحجة أن هذه الحجب تنفعه في أغراضه، ولا يرد له طلب، أو ينتصر على خصمه، ما صحة ذلك؟ مأجورين، وما حكمه؟","title":"حكم حمل الحُجُب لجلب نفع أو دفع ضر","answer":"الجواب: هذا باطل، لا أصل له، هذا باطل، ليس له أصل، فاتخاذ الحجب لا يجوز، وهي الحروز، ويقال لها: التمائم، والنبي ﷺ قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي لفظ آخر: من تعلق تميمة فقد أشرك وقال -عليه الصلاة والسلام-: إن الرقى والتمائم والتولة شرك. فالرقى التي لا تعرف لا تجوز، وأما الرقى الشرعية فلا بأس بها؛ لقوله ﷺ: لا بأس بالرقى ما لم تكن شركًا والتمائم: هي الحرز، وهي الحجب لا تجوز، سواء كانت من القرآن، أو من غير القرآن، أو مخلوطة، كلها لا تجوز؛ لأن الرسول ﷺ نهى عنها، وحذر منها، وأخبر أنها من الشرك، سواء كان المتخذ لها رجلًا أو امرأة، لا يجوز اتخاذها أبدًا، بل يجب الإنكار على من فعل ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13902/حكم-حمل-الحجب-لجلب-نفع-او-دفع-ضر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50002.mp3","categories":["الرقى والتمائم"]},{"id":15677,"question":"إذا مرض شخص، يدعون الشيخ يداويه، وهو يعمل حرزًا؛ وذلك إذا كان المرض من جنون، أو من سحر، ويرش عليه الدم المسفوح، هل كان هذا في عهد النبي ﷺ والصحابة؟","title":"حرمة التداوي بالدم المسفوح والحروز","answer":"الجواب: هذا منكر، أعوذ بالله، رشه بالدم المسفوح هذا منكر، نجس، لا يجوز هذا، وكذلك عمل الحروز كونه يكتب له حروزًا يعلقها في رقبته، أو في عضده، أو في غير ذلك، فهذا كله لا يجوز، الرسول -عليه الصلاة والسلام- قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، من تعلق تميمة فقد أشرك. المقصود: الرسول ﷺ نهى عن هذا، تعليق الحروز، وهي التمائم في أوراق، أو في خرق، أو في جلود، فيها دعوات أو آيات أو طلاسم، كل هذا لا يجوز، لا يعلق لا في يد المريض، ولا في رقبته، ولا في غير ذلك؛ لأن الرسول نهى عن هذا -عليه الصلاة والسلام-، قال ﷺ: من تعلق تميمة فلا أتم الله له، من تعلق ودعة فلا ودع الله له، من تعلق تميمة فقد أشرك. فالواجب على أهل الإسلام ترك هذه الأشياء المنكرة؛ لأن الرسول نهى عنها -عليه الصلاة والسلام-، وأما صب الدم النجس فهذا منكر ظاهر، والمسفوح: هو المراق الذي عند الذبح يخرج من البهيمة عند الذبح، هذا نجس ومحرم، فالواجب على المسلم أن يحذر ما حرم الله عليه. أما إذا قرأ عليه القرآن، قرأ عليه الفاتحة، آية الكرسي، ونفث عليه، ودعا له، هذا طيب......، وهكذا لو أخذ له دواء من الأطباء العارفين، وعالجه ببعض الطب بالدواء لا بأس، الرسول -عليه الصلاة والسلام- قال: ما أنزل الله داءً إلا أنزل له شفاء فالدواء لا بأس به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14221/حرمة-التداوي-بالدم-المسفوح-والحروز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70608.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":16509,"question":"سماحة الشيخ حفظكم الله، ما أفضل الأدعية الجامعة في القراءة على المريض؟ وأيضًا ما هي الآيات الواردة في ذلك؟","title":"الآيات والأدعية الواردة في رقية المريض","answer":"الجواب: من الأدعية الجامعة الواردة قوله ﷺ: أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا هذه من أجمع الدعاء، وأصح الدعاء، أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا ومن ذلك: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك كما رقى جبرائيل النبي ﷺ بهذه الرقية الأخيرة، ومن ذلك: (اللهم اشفه وعافه، اللهم اشفه وعافه، نسأل الله لك الشفاء والعافية) دعاء، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15218/الايات-والادعية-الواردة-في-رقية-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58303.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17182,"question":"هذا سائل للبرنامج سماحة الشيخ أرسل بسؤالٍ يستفسر فيه، ويقول: هل يجوز في الرقية أن يقرأ المسلم القرآن الكريم، وبعض الأدعية النبوية على الماء، أو الزيت، ويقوم المريض بشرب ذلك الماء، والاغتسال به؟ وإذا كان لا يجوز، فما الرقية الشرعية، والشروط التي يجب أن تتوفر في الرقية، ويجوز أن يستعملها المسلم بعد ذلك؟","title":"حكم الرقية على ماء وشربه والاغتسال به","answer":"الجواب: لا حرج في الرقية في الماء، ثم يشرب مثل المريض، أو يغتسل به، كل هذا لا بأس به، الرقية تكون على المريض بالنفث عليه، وتكون في ماء يشربه المريض، أو يتروش به، كل هذا لا بأس به، وقد ثبت عن النبي ﷺ أنه: رقى لثابت بن قيس بن شماس في ماء، ثم صبه عليه. فإذا رقى الإنسان أخاه في ماء، ثم شرب منه، أو صبه عليه يرجى فيه العافية والشفاء، وإذا قرأ لنفسه على العضو المريض، يده، أو رجله، أو صدره، ونفث عليه، ودعا له بالشفاء؛ فهذا كله حسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16000/حكم-الرقية-على-ماء-وشربه-والاغتسال-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59010.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17406,"question":"سائل فضيلة الشيخ هذا ..... أمجد، يستفسر عن معنى حديث قال رسول الله ﷺ للصحابة: ما الذي تخوضون فيه؟ فأخبروه عن أولئك الناس، فقال: هم أولئك الذين لا يرقون، ولا يتطيرون، وعلى ربهم يتوكلون؟","title":"شرح حديث الذين يدخلون الجنة بغير حساب","answer":"الجواب: هذا جاء في حديث السبعين، النبي ﷺ أخبر أصحابه أنه عرضت عليه أمته، وكان فيهم سبعون ألفًا يدخلون الجنة بغير حساب، ولا عذاب، فخاض الناس في أولئك: من هم؟ لما حدث بهذا الحديث، وقام -عليه الصلاة والسلام- خاضوا، فقال بعضهم: فلعلهم الذين ولدوا في الإسلام، وقال بعضهم: فلعلهم الذين صحبوا الرسول ﷺ يعني: من الصغر، ولم يكفروا، وخاضوا في غير هذا. ثم خرج عليهم ﷺ قال: ما ... ؟ سألهم عما يخوضون فيه، فأخبروه، فقال: هم الذين لا يسترقون، ولا يتطيرون، ولا يكتوون، وعلى ربهم يتوكلون هذه من صفاتهم، مع تقواهم لله، وإيمانهم بالله، واستقامتهم على دينه، هم مع هذا لا يسترقون يعني: لا يسألون الناس أن يرقوهم.  ولا يتطيرون الطيرة: التشاؤم بالمرئيات، والمسموعات، هذه الطيرة ما أمضاك، أو ردك بسبب التشاؤم. ولا يكتوون يعني: إذا مرضوا ما يكتوون. وعلى ربهم يتوكلون هذه من صفاتهم العظيمة.  ولكن يجوز الكي، الرسول ﷺ رخص في الكي، ويجوز الاسترقاء، رخص في الاسترقاء أيضًا لعائشة، وأم أولاد جعفر، لا حرج في الاسترقاء، كونه يطلب من يرقيه لا حرج، لكن تركه أفضل إذا تيسر دواء آخر غير الاسترقاء أفضل، وهكذا الكي لا بأس به عند الحاجة إليه؛ لقوله ﷺ: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل، وما أحب أن أكتوي.  أما الطيرة لا تجوز أبدًا ... محرمة؛ لأنها تشاؤم، لا يجوز، أما رواية: لا يرقون فهي رواية ضعيفة، رواها مسلم، ولكنها ضعيفة، غلط من بعض الرواة: لا يرقون فإن رقية الإنسان لأخيه مطلوبة، كونك ترقي أخاك هذا مشروع، النبي  قال: لا بأس بالرقى ما لم تكن شركًا وقد رقى النبي ﷺ بعض أصحابه، ورقي ﷺ رقته عائشة -رضي الله عنها- لما مرض، والصحابة رقى بعضهم بعضًا، لا بأس بالرقية. أما الاسترقاء كونه يقول: \"اقرأ لي يا فلان\" هذا تركه أفضل إلا عند الحاجة، إلا عند الحاجة، إذا احتاج للاسترقاء؛ لا حرج؛ لقوله لعائشة: استرقي ولقوله لأم أولاد جعفر: استرقي فلا حرج في ذلك، إنما الاسترقاء تركه أفضل؛ لأنه سؤال للناس، وشحاذة، وتركه أفضل. فإن دعت الحاجة إليه كالكي، إذا دعت الحاجة إليه؛ لا بأس، لا بأس أن يقول: يا أخ فلان اقرأ علي -جزاك الله خيرًا- أو يذهب إلى الراقي يرقى عليه، لا بأس، أو يكوي عند الحاجة إذا ظن أن الكي مفيد في هذا الشيء؛ فلا بأس، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16265/شرح-حديث-الذين-يدخلون-الجنة-بغير-حساب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77107.mp3","categories":["شروح الحديث","الرقى والتمائم"]},{"id":17408,"question":"سماحة الشيخ! يستفسر الكثير الحقيقة من الناس عن كيفية الرقية الشرعية؟","title":"كيفية الرقية الشرعية","answer":"الجواب: الرقية الشرعية هي الرقية بالآيات، والدعوات الطيبة هذه ... الشرعية، الرقية بالقرآن، أو بالدعوات الطيبة، يرقي بالفاتحة، بآية الكرسي، بغيرها من الآيات: قل هو الله أحد المعوذتين بغيرها، هذه الرقية الشرعية، أو بالدعاء يدعو له .... أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد الله يشفيك، باسم الله أرقيك.  أو اللهم اشفه وعافه، اللهم أنزل عليه الشفاء، اللهم أبرئه من مرضه.. وما أشبه ذلك الدعوات الطيبة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16267/كيفية-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77108.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17647,"question":"يقول السائل: ما حكم الشرع في التمائم والرقى؟","title":"حكم الشرع في التمائم والرقى","answer":"الجواب: التمائم لا تجوز، الحروز، ما يجوز تعليق التمائم، والرسول ﷺ نهى عنها قال: من تعلق تميمةً فلا أتم الله له، من تعلق تميمةً فقد أشرك فلا يجوز تعليق التمائم؛ لا من الحديد ولا من غيره ولا من الرقى، أما كونه يرقى عليه ينفث عليه إذا كان مريضًا ينفث عليه، لا بأس رقية شرعية، أما كونه يكتب كتابًا ويعلقه عليه، أو معضدًا يعلقه عليه، أو حديدة يعلقها عليه، كل هذا لا يجوز؛ لأن الرسول ﷺ نهى عن هذا قال: من تعلق تميمةً فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16576/حكم-الشرع-في-التماىم-والرقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59421.mp3","categories":["الرقى والتمائم"]},{"id":17771,"question":"تقول الأخت من الزلفي يا سماحة الشيخ: علاج العين هل نكتفي بالرقية الشرعية؟ أم لابد من الاغتسال من العائن؟","title":"كيفية العلاج من العين","answer":"الجواب: الرقية الشرعية علاج، والاغتسال علاج، إذا تيسر أن العائن يغتسل، يعني: لو ما اغتسل المقصود... يغسل وجهه ويتمضمض، ويغسل داخلة إزاره وأطراف قدميه، ينفع هذا، يصب على المريض ويغتسل به المعين؛ هذا ينفعه بإذن الله، وإن غسل وجهه وتمضمض في إناء وصبوه على المريض؛ نفع بإذن الله.\nلو ما اغتسل، المقصود كونه يغسل وجهه ويتمضمض ويغسل يديه وداخلة إزاره وأطراف قدميه وركبتيه هذا ينفع في علاج المعين، وقد جربنا أن غسل الوجه والمضمضة وغسل اليدين وحده يكفي بإذن الله في إزالة العين، فإذا اتهم إنسان بهذا وغسل وجهه ويديه وتمضمض في إناء، ثم صب على المريض؛ يبرأ بإذن الله.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16744/كيفية-العلاج-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59622.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":18253,"question":"نختم هذا اللقاء سماحة الشيخ بهذا السؤال من( أحمد أ. أ )، يقول: بالنسبة لبعض الشباب يضعون في السيارة المصحف؛ وذلك خشية من العين؟","title":"حكم وضع المصحف في السيارة بنية دفع العين","answer":"الجواب: هذا لا أصل له، بل بدعة، بل من جنس التميمة من جنس الحروز، ولكن يقرأ إذا ركب يقول: أعوذ بكلمات الله التامات من شر ما خلق يسأل ربه العافية. أما وضع المصحف أو آيات بناء على أنه حرز هذا لا أصل له، بل هذا من البدع، وهذا من جنس تعليق التمائم لا يجوز، والله المستعان لا حول ولا قوة إلا بالله. المقدم: الله المستعان، شكر الله لكم سماحة الشيخ! وبارك الله فيكم، وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17302/حكم-وضع-المصحف-في-السيارة-بنية-دفع-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78309.mp3","categories":["الرقى والتمائم"]},{"id":18320,"question":"تقول: عند زيارتي لبيت جدي أرى أنهم يعلقون حجرًا على الحائط ظنًا منهم أنه يمنع الحسد، ويسمى لدينا: سبع عيون، ولقد أوضحت لجدتي أن هذا شرك بالله، وأنه يجب أن يكون التوكل على الله وحده، ولا نستعين بغيره، إلا أنها لم تأخذ بنصيحتي، وبعد فترة وبدون علم منها، أخذته وحطمته، وهي حتى الآن لا تعلم من أخذه، فهل علي إثم في عدم إخبارها بأني أنا فعلت ذلك؟ مع علمي بأنها ستغضب علي لو قلت لها: أنا فعلت ذلك، هل لي أجر فيما فعلت؟ جزاكم الله خيرًا.","title":"حكم إزالة ما يعتقد فيه أنه يمنع الحسد","answer":"الجواب: قد أحسنت في هذا، وجزاك الله خيرًا، ولا تخبريها، لا تخبريها، وقد أحسنت في نصيحتها، والحمد لله، قد أفهمتيها، ونصحتيها، ولا حاجة إلى إخبارها بمن أزاله، وهو يشبه التميمة اللي تعلق على الأولاد، أو غير الأولاد، من باب الشرك الأصغر؛ لأنهم يعتقدون في الحجر هذا أنه يدفع عنهم العين، أو الحسد، هذا شيء لا أصل له، بل هو من جنس تعليق التمائم على الأولاد من حروز، أنها تدفع العين، أو تدفع الجن، وهذا من الشرك الأصغر، ومن المنكر، فهذا يشبهه، فقد أحسنت في إزالته. أما لو اعتقد أن هذا الحجر، أو هذه التميمة تتصرف في الكون بغير إذن الله، وأنها تنفع وتضر، يكون شركًا أكبر، لكن في الغالب على الناس أنهم يقصدون أنها سبب، سبب لمنع العين، أو منع الحسد، وهذا باطل لا أصل له، لا في التميمة التي تعلق على الأولاد أو غيرهم، ولا في الحجر الذي يعلق على باب أو جدار، نسأل الله السلامة. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17373/حكم-ازالة-ما-يعتقد-فيه-انه-يمنع-الحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73207.mp3","categories":["الرقى والتمائم"]},{"id":18794,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ المستمع هياف ناصر الهياف التميمي، أخونا عرضنا جزءًا من أسئلته في حلقات مضت، وفي هذه الحلقة يسأل ويقول: هل يجوز تعليق الآيات في البيوت أم لا يجوز، أم أن ذلك بدعة؟أفيدونا، جزاكم الله خيرًا.","title":"هل يجوز تعليق الآيات في البيوت أم لا؟","answer":"الجواب: بسم الله الرحمن الرحيم  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا حرج في تعليق الآيات والأحاديث في المكاتب والمجالس ونحو ذلك للفائدة والذكرى. وأما تعليقها على الإنسان كالمريض، أو الصغير كتميمة؛ لحفظه من الجن أو كذا هذا لا يجوز؛ ولهذا ثبت عنه ﷺ أنه قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وفي رواية أخرى: من تعلق تميمة فقد أشرك. فالتمائم: هي التي تعلق على الأولاد أو على المرضى، إما لقصد حفظهم بزعم المعلق من الجن، أو من العين، وهذا لا يجوز، أما تعليق آيات أو أحاديث في مكاتب ونحوها لقصد الفائدة والذكرى فلا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17916/هل-يجوز-تعليق-الايات-في-البيوت-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92101.mp3","categories":["الرقى والتمائم"]},{"id":18841,"question":"يسأل أخونا أيضًا ويقول: عندنا إمام لمسجدنا ومدرس للمواد الدينية، يأتي إليه المرضى فيعمل لهم حرزًا، أو بيض الدجاجة يكسرها في بيت المريض في محافظتنا، هل تصح الصلاة وراءه حفظكم الله؟","title":"حكم الصلاة خلف من يعمل التمائم والودع","answer":"الجواب: هذا خطير، ومنكره عظيم، لا يجوز أن يفعل هذا الفعل؛ فإن اتخاذ الحروز منكر، وهي التمائم وتسمى: الحجب، ويسميها بعض الناس: الجوامع فلا تجوز، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له. والتميمة: هي الحرز، وهي الجامعة في عرف الناس اليوم، وهي الحجاب كما يسميها بعض الناس، وهي شيء يعلق على الأولاد، أو على المرضى، أو على الكبار، عن العين، أو عن الجن، يكتبون كتابات في رقع، أو يضعون ودع أو خرز، أو يضعون طلاسم حروف مقطعة لا يدرى ما معناها، يكتبونها ويجعلونها في رقع، ويربطونها على الصبيان أو على المرضى أو على الكبار؛ يزعمون أنها تدفع العين، أو تدفع الجن، كل هذا باطل، كل هذا غلط ومنكر؛ لأن الرسول أنكرها -عليه الصلاة والسلام-. فالواجب على المؤمن أن يحذر ذلك، وألا يفعل ذلك، وهذا من الشرك، وهو من الشرك الأصغر، لكن إذا كان صاحبه يعتقد أنها تنفع وتضر دون الله؛ فهذا يكون شركًا أكبر -نعوذ بالله-. فالحاصل: أنه لا يجوز تعاطي هذا الشيء، وهكذا كسر البيضة في بيت المريض، أو بيت زيد أو عمرو، يعتقد أنها تنفعه، هذا خرافة لا أساس لها، بل هو من الدجل والكذب والخداع، فمثل هذا لا ينبغي أن يتخذ إمامًا، ولا يؤمن أن يكون عنده عقائد خبيثة أكثر من هذا، فينبغي أن لا يصلى خلفه، وينبغي أن يبعد من الإمامة، ويسعى في ذلك، إلا أن يتوب توبة صادقة ظاهرة بارزة واضحة؛ فالتوبة تجب ما قبلها، والله المستعان. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/17984/حكم-الصلاة-خلف-من-يعمل-التماىم-والودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87804.mp3","categories":["صلاة الجماعة","الرقى والتمائم"]},{"id":19086,"question":"ننتقل إلى رسائل أخرى من رسائل إخواننا المستمعين، رسالة وصلت إلى البرنامج من جمهورية السودان، وباعثها شيبة كمال أبو علي، أخونا رسالته مطولة في الواقع وهي تهتم بأمر التوحيد، لكن ملخص الرسالة هذا  ما حكم التمائم؟ مع ذكر الدليل لكي تتضح المسألة؟ جزاكم الله خيرًا.","title":"ما حكم تعليق التمائم؟","answer":"الجواب: تعليق التمائم من المحرمات الشركية، والتمائم: هي ما يكتب في الرقاع من خرق، أو قراطيس، أو رقاع من الجلد أو غير ذلك، يكتب فيها طلاسم لا تعرف معناها، وربما يكتب فيها أسماء لبعض الشياطين بعض الجن، وربما كتب فيها دعوات أو آيات، ثم تعلق على المريض أو على الطفل، يزعمون أنها تدفع عنهم الجن، وبعضهم يعلقها لدفع العين، وكانت الجاهلية تفعل ذلك تعلق التمائم على الأولاد والأوتار على الإبل، ويزعمون أنها تدفع عنهم البلاء، وهذا من الجهل بالله وقلة البصيرة. ولهذا أمر النبي بقطع التمائم عليه الصلاة والسلام، وقال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، ومن تعلق تميمة فقد أشرك. ونهى عن تعليق الأوتار على الدواب وبعث في الجيوش من يزيل ذلك ويقطع الأوتار التي تعلق على الإبل أو الخيل. فالمقصود أن تعليق الأوتار والتمائم أمر كان معروفًا في الجاهلية، فنهى عنه النبي ﷺ وأبطله. والتعليق للتمائم والأوتار عند أهل العلم من الشرك الأصغر إذا كان قصد المعلق أنها سبب، أما إذا كان قصد المعلق أنها تدفع بنفسها وأنها تصرف السوء بنفسها هذا شرك أكبر نعوذ بالله. وهناك مسألة اختلف فيها العلماء، وهي ما إذا كانت التمائم من القرآن أو من الدعوات الطيبة وليس فيها طلاسم ولا شركيات ولا أشياء منكرة، هل تجوز أم لا تجوز؟ أجازها بعض السلف وقالوا: إنها من جنس الرقية، وأجازوا تعليق التمائم التي من القرآن أو من دعوات لا بأس بها. وقال آخرون من أهل العلم: لا تجوز بل جوازها فتح لباب الشرك. وقالوا: إن الرسول ﷺ نهى عن التمائم وأطلق ولم يخص شيئًا دون شيء، بل قال: من تعلق تميمة فلا أتم الله له .. من تعلق تميمة فقد أشرك هذا عام. وقال: إن الرقى والتمائم والتولة شرك فإذا أجزنا التمائم من القرآن فقد خالفنا هذه الأحاديث العامة، والعموم حجة يجب الأخذ به، ثم إذا أجزنا هذه التمائم من القرآن صار فتحًا لباب الشرك، فإنها تلتبس الأمور وتختلط هذه بهذه، ويلبس الناس هذه بهذه فيقع الشرك، وقد جاءت الشريعة بسد الذرائع بأدلة كثيرة، كل شيء يفضي إلى الشرك أو إلى المحرمات يمنع، ولا شك أن تعليق التمائم من القرآن أو من الدعوات المباحة يخالف الأحاديث العامة والنهي العام، ويسبب فتح باب الشرك واختلاط الأمور فلهذا الصواب منع الجميع. الصواب منع التمائم كلها من القرآن وغير القرآن؛ أخذًا بعموم الأحاديث وسدًا لباب الشرك، والله المستعان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18250/ما-حكم-تعليق-التماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_930/nour_93002.mp3","categories":["الرقى والتمائم"]},{"id":19358,"question":"يسأل أخونا ويقول: ما رأي سماحتكم في القلائد أي: كتابة الآيات القرآنية، ووضعها في قطعة قماش، وتعليقها على جسم الشخص أو تحت الوسادة؟","title":"حكم كتابة الآيات، وتعليقها على جسم الشخص أو تحت الوسادة؟","answer":"الجواب: تعليق التمائم ويقال لها: الحروز، ويقال لها أيضًا: الجوامع، لا يجوز؛ لأن الرسول عليه الصلاة والسلام قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له وقال: من تعلق تميمة فقد أشرك، وقال: إن الرقى، والتمائم، والتولة شرك. فهذه الأحاديث وما جاء في معناها تدل على منع التمائم، وأنه لا يجوز تعليقها على المريض، ولا على الطفل، ولا جعلها تحت الوسائد كل ذلك لا يجوز؛ لأنه من عمل الجاهلية؛ ولأنه يسبب تعلق القلوب بهذه القلائد، وصرفها عن الله ؛ ولأنه أيضًا يفضي إلى التعلق بها، والاعتقاد فيها، وأنها تصرف عنه البلاء، وكل شيء بيد الله لا بيدها، ليس بيد التمائم شيء، بل الله هو النافع الضار، وهو الحافظ لعباده، وهو مسبب الأسباب. فلا يجوز للمسلم أن يتعاطى شيئًا من الأسباب التي يظن أنها أسباب إلا بإذن الشرع كالقراءة على المريض، والتداوي بالأدوية المباحة، هذه أذن فيها الشرع، أما التمائم فلم يأذن فيها الشرع تعليقها على الأغراض والأطفال هذه لم يأذن فيها الشرع بل نهى عنها للأسباب التي سبق ذكرها.\nواختلف أهل العلم فيما يتعلق بالتمائم التي تكون من القرآن، أو من الدعوات المباحة هل تجوز أم لا؟ والصواب: أنها لا تجوز لأمرين:\nأحدهما: أن الأدلة الدالة على منع التمائم مطلقة عامة ليس فيها استثناء بخلاف الرقى فإنه يجوز منها ما ليس فيه شرك لقوله ﷺ: لا بأس بالرقى ما لم تكن شركًا فقوله ﷺ: إن الرقى، والتمائم، والتولة شرك هذا عام لكن جاءت الأحاديث باستثناء الرقى التي ليس فيها بأس، وهي ما يكون من القرآن، ومن الدعوات الطيبة؛ هذا لا بأس بها لقوله ﷺ: لا بأس بالرقى ما لم تكن شركًا، ولأنه رَقى ورُقي عليه الصلاة والسلام، فلا بأس بذلك. أما التمائم فلم يأت فيها استثناء فتبقى على العموم والمنع، وهكذا التولة وهي نوع من السحر يتعاطاها النساء، وتسمى الصرف والعطف، صرف الرجل عن زوجته إلى غيرها، أو عطفه عليها دون غيرها، وهو من السحر وهذا منكر لا يجوز، بل من المحرمات الشركية. المقدم: سواءً كان الصرف أو العطف شيخ عبد العزيز؟\nالشيخ: كله سواء، كله ممنوع، كله من السحر ولا يجوز، وأما التمائم التي من العظام، أو من الودع، أو من شعر الذئب، أو من حيوانات أخرى هذه كلها محرمة لا تجوز، وليس فيها نزاع بل هي ممنوعة، وإنما النزاع والخلاف فيما إذا كانت التمائم من القرآن، أو من دعوات معلومة؛ لا بأس بها فهذه هي محل الخلاف. والصواب: أنها ممنوعة أيضًا لما تقدم من كون الأحاديث عامة في منع التمائم، ولم يستثن الرسول منها شيئًا عليه الصلاة والسلام. ولأمر ثاني: وهو سد الذرائع التي تفضي إلى الشرك، فإنها متى سمح بالتمائم التي من القرآن، أو الدعوات المباحة؛ التبس الأمر، وعلقت هذه وهذه، ولم يتميز الممنوع من الجائز، وقد جاءت الشريعة بسد الذرائع، والنهي عن وسائل الشرك كلها، فوجب منع التمائم كلها لهذين المعنيين والسببين: عموم الأدلة، وسد الذرائع. وذكر بعض أهل العلم مانعًا ثالثًا: وهو أن تعليقها وسيلة إلى أن يدخل بها صاحبها محلات قضاء الحاجة ولا يبالي، وفيها آيات قرآنية، فيكون ذلك من أسباب امتهانها امتهان الآيات. وعلى كل حال فهذا وجه من المنع لكن المعنيين الأولين أوضح في الحجة، وأبين في المنع، وهما: عموم الأدلة، وليس هناك استثناء لشيء من التمائم. والمعنى الثاني: سد الذرائع التي تفضي إلى الشرك، ولا ريب أن إجازة التمائم التي من القرآن، أو من الدعوات المباحة والأسباب المباحة لا شك أنها وسيلة إلى تعليق النوعين، ولا حول ولا قوة إلا بالله. المقدم: جزاكم الله خيرًا ونفع بكم.","link":"https://binbaz.org.sa/fatwas/18581/حكم-كتابة-الايات-وتعليقها-على-جسم-الشخص-او-تحت-الوسادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_942/nour_94205.mp3","categories":["الرقى والتمائم"]},{"id":19511,"question":"سماحة الشيخ! هذا سائل يقول: ما كيفية الرقية بالدعاء يا سماحة الشيخ! وما هي الأدعية التي تقرأ؟","title":"صفة الرقية الشرعية","answer":"الجواب: ينفث على المريض على محل المرض، ويدعو له، ينفث عليه من ريقه، ويقرأ الفاتحة، ويكررها سبع مرات، ويقرأ آية الكرسي، ويقرأ ما تيسر من القرآن، ويقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] والمعوذتين يكررها ثلاثًا، هذه الرقية وينفث معها ويدعو الله، اللهم أذهب الباس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا كما فعله النبي ﷺ. ويقول: باسم الله أرقيك من كل شيء يؤذيك، من شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك هكذا رقى جبرائيل النبي عليه الصلاة والسلام كما أخبر بذلك النبي عليه الصلاة والسلام فكل هذا حسن. وإذا قال: اللهم اشفه، اللهم عافه، اللهم يسر له العافية والدعوات المناسبة لا بأس، لكن هذا الدعاء الشرعي الوارد عن النبي ﷺ: اللهم أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا، باسم الله أرقيك من كل شيء يؤذيك، من شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، وإذا رقى بدعوات أخرى للمريض بطلب العافية فلا بأس. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18771/صفة-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94613.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":19558,"question":"هذا سائل يقول: يا سماحة الشيخ! ما هي الأحاديث التي يقرؤها المريض على نفسه؟ وهل يضع يده على موطن الألم في جسده عند القراءة؟","title":"كيفية رقية المريض نفسه","answer":"الجواب: ما أعلم في هذا شيئًا خاصًا، يقرأ القرآن، ويقرأ ما تيسر من الحديث، ويكثر من الدعاء، والاستغفار، وإذا وضع يده على الألم ودعا فهذا حسن، النبي ﷺ لما سأله عثمان بن أبي العاص عن علاج مرضه أمره أن يضع يده على محل الألم ويقول: اللهم .. يسأل ربه جل وعلا، هذا لا بأس، إذا وضع يده على الألم وتعوذ بالله واستعاذ بالله من هذا المرض يرجى له الإجابة. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18808/كيفية-رقية-المريض-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94707.mp3","categories":["الرقى والتمائم"]}]
